package com.goldmanmode;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * All the areas plus a fast tile -> area lookup.
 * If two areas overlap, the smaller one owns the overlapping tiles.
 */
public class AreaIndex
{
	private final List<GoldmanArea> areas;
	/** region (x>>6, y>>6) -> 64x64 grid of (area index + 1), 0 = no area */
	private final Map<Long, short[]> grid = new HashMap<>();

	public AreaIndex(List<GoldmanArea> areas)
	{
		this.areas = areas;
		build();
	}

	public List<GoldmanArea> getAreas()
	{
		return areas;
	}

	private BarrierGeometry barrier;

	/** straight outline pieces of every area (built on first use) */
	public synchronized BarrierGeometry getBarrier()
	{
		if (barrier == null)
		{
			barrier = new BarrierGeometry(areas);
		}
		return barrier;
	}

	public GoldmanArea get(int idx)
	{
		return areas.get(idx);
	}

	/** @return index into {@link #getAreas()} or -1 */
	public int indexAt(int x, int y)
	{
		short[] g = grid.get(key(x >> 6, y >> 6));
		if (g == null)
		{
			return -1;
		}
		return g[(x & 63) | ((y & 63) << 6)] - 1;
	}

	public GoldmanArea areaAt(int x, int y)
	{
		int i = indexAt(x, y);
		return i < 0 ? null : areas.get(i);
	}

	private static long key(int rx, int ry)
	{
		return ((long) rx << 32) | (ry & 0xFFFFFFFFL);
	}

	private void build()
	{
		for (int i = 0; i < areas.size(); i++)
		{
			GoldmanArea a = areas.get(i);
			a.setTiles(rasterise(a), i);
		}
		// smaller areas claim tiles first, so an area drawn inside a bigger one wins
		Integer[] order = new Integer[areas.size()];
		for (int i = 0; i < order.length; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, Comparator.comparingInt((Integer i) -> areas.get(i).getSize()).thenComparingInt(i -> i));
		for (int i : order)
		{
			for (int t : areas.get(i).getTiles())
			{
				int x = t >>> 16, y = t & 0xFFFF;
				short[] g = grid.computeIfAbsent(key(x >> 6, y >> 6), k -> new short[64 * 64]);
				int li = (x & 63) | ((y & 63) << 6);
				if (g[li] == 0)
				{
					g[li] = (short) (i + 1);
				}
			}
		}
	}

	/** Tiles whose centre lies inside the area (even-odd per part, so holes are cut out). */
	static int[] rasterise(GoldmanArea area)
	{
		java.util.BitSet seen = new java.util.BitSet();
		int w = area.getMaxX() - area.getMinX() + 1;
		int count = 0;
		int[] out = new int[256];
		for (List<double[][]> part : area.getParts())
		{
			double minY = Double.MAX_VALUE, maxY = -Double.MAX_VALUE;
			for (double[][] ring : part)
			{
				for (double[] p : ring)
				{
					minY = Math.min(minY, p[1]);
					maxY = Math.max(maxY, p[1]);
				}
			}
			if (minY > maxY)
			{
				continue;
			}
			double[] xs = new double[64];
			for (int ty = (int) Math.floor(minY); ty <= (int) Math.ceil(maxY); ty++)
			{
				double yc = ty + 0.5;
				int n = 0;
				for (double[][] ring : part)
				{
					int len = ring.length;
					for (int i = 0; i < len; i++)
					{
						double[] a = ring[i], b = ring[(i + 1) % len];
						if ((a[1] <= yc && b[1] > yc) || (b[1] <= yc && a[1] > yc))
						{
							if (n == xs.length)
							{
								xs = Arrays.copyOf(xs, n * 2);
							}
							xs[n++] = a[0] + (yc - a[1]) * (b[0] - a[0]) / (b[1] - a[1]);
						}
					}
				}
				Arrays.sort(xs, 0, n);
				for (int i = 0; i + 1 < n; i += 2)
				{
					int from = (int) Math.ceil(xs[i] - 0.5);
					int to = (int) Math.ceil(xs[i + 1] - 0.5) - 1;
					for (int tx = from; tx <= to; tx++)
					{
						int bit = (ty - area.getMinY()) * w + (tx - area.getMinX());
						if (tx < 0 || ty < 0 || bit < 0 || seen.get(bit))
						{
							continue;
						}
						seen.set(bit);
						if (count == out.length)
						{
							out = Arrays.copyOf(out, count * 2);
						}
						out[count++] = (tx << 16) | ty;
					}
				}
			}
		}
		return Arrays.copyOf(out, count);
	}

	// ------------------------------------------------------------------ loading

	public static AreaIndex load(InputStream in) throws IOException
	{
		try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			return parse(new JsonParser().parse(r));
		}
	}

	public static AreaIndex parse(String json)
	{
		return parse(new JsonParser().parse(json));
	}

	/**
	 * Accepts a list of areas as exported from the drawing page:
	 * [{id, n, c, t, parts:[{p:[[x,y],..], h:[[[x,y],..],..]}]}]
	 * (the raw database form {n, p, h, x:[{p,h}], c, t} also works).
	 */
	static AreaIndex parse(JsonElement root)
	{
		List<GoldmanArea> list = new ArrayList<>();
		JsonArray arr = root.isJsonArray() ? root.getAsJsonArray() : new JsonArray();
		int n = 0;
		for (JsonElement el : arr)
		{
			JsonObject o = el.getAsJsonObject();
			List<List<double[][]>> parts = new ArrayList<>();
			if (o.has("parts") && o.get("parts").isJsonArray())
			{
				for (JsonElement pe : o.getAsJsonArray("parts"))
				{
					addPart(parts, pe.getAsJsonObject());
				}
			}
			else
			{
				addPart(parts, o);
				if (o.has("x") && o.get("x").isJsonArray())
				{
					for (JsonElement pe : o.getAsJsonArray("x"))
					{
						addPart(parts, pe.getAsJsonObject());
					}
				}
			}
			if (parts.isEmpty())
			{
				continue;
			}
			String id = o.has("id") ? o.get("id").getAsString() : "area" + n;
			String name = o.has("n") && !o.get("n").isJsonNull() && !o.get("n").getAsString().trim().isEmpty()
				? o.get("n").getAsString().trim() : "Unnamed area " + (n + 1);
			int c = o.has("c") && !o.get("c").isJsonNull() ? o.get("c").getAsInt() : 0;
			String t = o.has("t") && !o.get("t").isJsonNull() ? o.get("t").getAsString() : "";
			long price = o.has("price") && !o.get("price").isJsonNull() ? o.get("price").getAsLong() : -1;
			list.add(new GoldmanArea(id, name, c, t, parts, price));
			n++;
		}
		return new AreaIndex(list);
	}

	private static void addPart(List<List<double[][]>> parts, JsonObject po)
	{
		if (!po.has("p") || !po.get("p").isJsonArray())
		{
			return;
		}
		List<double[][]> rings = new ArrayList<>();
		double[][] outer = ring(po.getAsJsonArray("p"));
		if (outer.length < 3)
		{
			return;
		}
		rings.add(outer);
		if (po.has("h") && po.get("h").isJsonArray())
		{
			for (JsonElement he : po.getAsJsonArray("h"))
			{
				double[][] hole = ring(he.getAsJsonArray());
				if (hole.length >= 3)
				{
					rings.add(hole);
				}
			}
		}
		parts.add(rings);
	}

	private static double[][] ring(JsonArray pts)
	{
		double[][] r = new double[pts.size()][];
		for (int i = 0; i < r.length; i++)
		{
			JsonArray p = pts.get(i).getAsJsonArray();
			r[i] = new double[]{p.get(0).getAsDouble(), p.get(1).getAsDouble()};
		}
		return r;
	}
}

package com.goldmanmode;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The straight outline of every area in pieces of at most one tile, each remembering which area lies on either side.
 * Built once: which pieces get a barrier depends on what is locked. Following the drawn outline rather than tile
 * edges is what gives diagonal borders a straight barrier.
 */
public class BarrierGeometry
{
	/** how far either side of an edge we look to see which area is there (tiles) */
	private static final double PROBE = 0.25;

	public static class Piece
	{
		public final float x1, y1, x2, y2;
		/** area whose outline this piece is part of */
		public final int ring;
		/** area on each side (-1 = none) */
		public final int o1, o2;

		Piece(float x1, float y1, float x2, float y2, int ring, int o1, int o2)
		{
			this.x1 = x1;
			this.y1 = y1;
			this.x2 = x2;
			this.y2 = y2;
			this.ring = ring;
			this.o1 = o1;
			this.o2 = o2;
		}
	}

	private final List<GoldmanArea> areas;
	private final Map<Long, List<Integer>> areaBuckets = new HashMap<>();
	private final Map<Long, List<Piece>> pieceBuckets = new HashMap<>();
	private int count;
	/** pieces that cut through the inside of a tile (not just run along its edge), by tile */
	private final Map<Long, List<Piece>> crossing = new HashMap<>();

	public BarrierGeometry(List<GoldmanArea> areas)
	{
		this.areas = areas;
		for (int i = 0; i < areas.size(); i++)
		{
			GoldmanArea a = areas.get(i);
			for (int rx = a.getMinX() >> 6; rx <= a.getMaxX() >> 6; rx++)
			{
				for (int ry = a.getMinY() >> 6; ry <= a.getMaxY() >> 6; ry++)
				{
					areaBuckets.computeIfAbsent(key(rx, ry), k -> new ArrayList<>()).add(i);
				}
			}
		}
		for (int i = 0; i < areas.size(); i++)
		{
			for (double[][] ring : areas.get(i).getRings())
			{
				addRing(i, ring);
			}
		}
	}

	public int getPieceCount()
	{
		return count;
	}

	/** pieces whose midpoint is in the 64x64 region (rx, ry); may be null */
	public List<Piece> region(int rx, int ry)
	{
		return pieceBuckets.get(key(rx, ry));
	}

	private static long key(int rx, int ry)
	{
		return ((long) rx << 32) | (ry & 0xFFFFFFFFL);
	}

	private void addRing(int area, double[][] ring)
	{
		int n = ring.length;
		for (int i = 0; i < n; i++)
		{
			double[] a = ring[i], b = ring[(i + 1) % n];
			double dx = b[0] - a[0], dy = b[1] - a[1];
			double len = Math.sqrt(dx * dx + dy * dy);
			if (len < 1e-6)
			{
				continue;
			}
			double nx = -dy / len, ny = dx / len;
			int parts = Math.max(1, (int) Math.ceil(len));
			for (int k = 0; k < parts; k++)
			{
				double t0 = (double) k / parts, t1 = (double) (k + 1) / parts;
				double x1 = a[0] + dx * t0, y1 = a[1] + dy * t0;
				double x2 = a[0] + dx * t1, y2 = a[1] + dy * t1;
				double mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
				int o1 = owner(mx + nx * PROBE, my + ny * PROBE);
				int o2 = owner(mx - nx * PROBE, my - ny * PROBE);
				if (o1 == o2)
				{
					continue; // same area on both sides: never a border
				}
				Piece p = new Piece((float) x1, (float) y1, (float) x2, (float) y2, area, o1, o2);
				indexCrossings(p);
				pieceBuckets.computeIfAbsent(key((int) Math.floor(mx) >> 6, (int) Math.floor(my) >> 6), kk -> new ArrayList<>()).add(p);
				count++;
			}
		}
	}

	/** pieces of border that pass through the inside of tile (tx, ty); may be null. Edge-hugging pieces don't count. */
	public List<Piece> crossing(int tx, int ty)
	{
		return crossing.get(key(tx, ty));
	}

	/** how far inside a tile a piece must get to count as touching it (tile fractions) */
	private static final double MARGIN = 0.04;

	private void indexCrossings(Piece p)
	{
		int x0 = (int) Math.floor(Math.min(p.x1, p.x2)), x1 = (int) Math.floor(Math.max(p.x1, p.x2));
		int y0 = (int) Math.floor(Math.min(p.y1, p.y2)), y1 = (int) Math.floor(Math.max(p.y1, p.y2));
		for (int tx = x0; tx <= x1; tx++)
		{
			for (int ty = y0; ty <= y1; ty++)
			{
				if (entersSquare(p, tx + MARGIN, ty + MARGIN, tx + 1 - MARGIN, ty + 1 - MARGIN))
				{
					crossing.computeIfAbsent(key(tx, ty), k -> new ArrayList<>(2)).add(p);
				}
			}
		}
	}

	/** Liang-Barsky: does the segment pass through the rectangle? */
	private static boolean entersSquare(Piece p, double minX, double minY, double maxX, double maxY)
	{
		double t0 = 0, t1 = 1, dx = p.x2 - p.x1, dy = p.y2 - p.y1;
		double[] pp = {-dx, dx, -dy, dy};
		double[] qq = {p.x1 - minX, maxX - p.x1, p.y1 - minY, maxY - p.y1};
		for (int i = 0; i < 4; i++)
		{
			if (Math.abs(pp[i]) < 1e-9)
			{
				if (qq[i] < 0)
				{
					return false;
				}
			}
			else
			{
				double r = qq[i] / pp[i];
				if (pp[i] < 0)
				{
					t0 = Math.max(t0, r);
				}
				else
				{
					t1 = Math.min(t1, r);
				}
				if (t0 > t1)
				{
					return false;
				}
			}
		}
		return true;
	}

	/** index of the smallest area that geometrically contains the point, or -1 */
	int owner(double x, double y)
	{
		List<Integer> cand = areaBuckets.get(key((int) Math.floor(x) >> 6, (int) Math.floor(y) >> 6));
		if (cand == null)
		{
			return -1;
		}
		int best = -1;
		int bestSize = Integer.MAX_VALUE;
		for (int i : cand)
		{
			GoldmanArea a = areas.get(i);
			if (x < a.getMinX() || x > a.getMaxX() || y < a.getMinY() || y > a.getMaxY())
			{
				continue;
			}
			if (a.getSize() < bestSize && contains(a, x, y))
			{
				best = i;
				bestSize = a.getSize();
			}
		}
		return best;
	}

	static boolean contains(GoldmanArea a, double x, double y)
	{
		for (List<double[][]> part : a.getParts())
		{
			boolean in = false;
			for (double[][] ring : part)
			{
				int n = ring.length;
				for (int i = 0, j = n - 1; i < n; j = i++)
				{
					double yi = ring[i][1], yj = ring[j][1];
					if ((yi > y) != (yj > y) && x < (ring[j][0] - ring[i][0]) * (y - yi) / (yj - yi) + ring[i][0])
					{
						in = !in;
					}
				}
			}
			if (in)
			{
				return true;
			}
		}
		return false;
	}
}

package com.goldmanmode;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.awt.Color;
import java.awt.Graphics2D;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/** The game's own pixel font (RuneScape Plain 11), drawn pixel by pixel from a glyph table. */
final class BitmapFont
{
	private static final class Glyph
	{
		int topBearing, height, width, advance, leftBearing;
		boolean[] pixels;
	}

	private final Map<Integer, Glyph> glyphs = new HashMap<>();
	private final int ascent, maxDescent;

	private BitmapFont(JsonObject o)
	{
		ascent = o.get("ascent").getAsInt();
		maxDescent = o.get("maxDescent").getAsInt();
		for (JsonElement e : o.getAsJsonArray("glyphs"))
		{
			JsonObject g = e.getAsJsonObject();
			Glyph gl = new Glyph();
			gl.topBearing = g.get("topBearing").getAsInt();
			gl.height = g.get("height").getAsInt();
			gl.width = g.get("width").getAsInt();
			gl.advance = g.get("advance").getAsInt();
			gl.leftBearing = g.get("leftBearing").getAsInt();
			JsonArray px = g.getAsJsonArray("pixels");
			gl.pixels = new boolean[px.size()];
			for (int i = 0; i < gl.pixels.length; i++)
			{
				gl.pixels[i] = px.get(i).getAsInt() != 0;
			}
			glyphs.put(g.get("codePoint").getAsInt(), gl);
		}
	}

	static BitmapFont load()
	{
		try (InputStream in = BitmapFont.class.getResourceAsStream("RuneScape-Plain-11.json");
			Reader r = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			return new BitmapFont(new JsonParser().parse(r).getAsJsonObject());
		}
		catch (IOException | RuntimeException e)
		{
			throw new IllegalStateException("font missing or broken", e);
		}
	}

	/** height of a line of text, pixels */
	int lineHeight()
	{
		return ascent + maxDescent;
	}

	int width(String s)
	{
		int w = 0;
		for (int i = 0; i < s.length(); i++)
		{
			Glyph g = glyphs.get((int) s.charAt(i));
			w += g == null ? 4 : g.advance;
		}
		return w;
	}

	/** Draw s with the top-left of its line at (x, y). */
	void draw(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(c);
		int pen = x;
		for (int i = 0; i < s.length(); i++)
		{
			Glyph gl = glyphs.get((int) s.charAt(i));
			if (gl == null)
			{
				pen += 4;
				continue;
			}
			for (int row = 0; row < gl.height; row++)
			{
				int col = 0;
				while (col < gl.width)
				{
					if (!gl.pixels[row * gl.width + col])
					{
						col++;
						continue;
					}
					int start = col;
					while (col < gl.width && gl.pixels[row * gl.width + col])
					{
						col++;
					}
					g.fillRect(pen + gl.leftBearing + start, y + gl.topBearing + row, col - start, 1);
				}
			}
			pen += gl.advance;
		}
	}
}

package com.goldmanmode;

import java.awt.Point;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Hovering an item in the in-game collection log, or a quest in the quest list, shows "Pays 123,400" (white "Pays", yellow amount and gp).
 */
@Singleton
class ClogTooltip
{
	private final Client client;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;
	private final GoldmanAchievements achievements;

	@Inject
	ClogTooltip(Client client, ItemManager itemManager, TooltipManager tooltipManager, GoldmanAchievements achievements)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.achievements = achievements;
	}

	/** the tooltip text for a payout: white "Pays ", yellow amount */
	static String text(long gp)
	{
		return "<col=ffffff>Pays </col><col=ffff00>" + QuantityFormatter.formatNumber(gp) + " gp</col>";
	}

	/** call once a client tick (client thread) */
	void onClientTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		questTooltip();
		clogTooltip();
	}

	/**
	 * the quest list on the quest tab: every row is a text widget holding the quest's name. Rather than trust which
	 * container holds the rows, look through everything under the quest list for the text under the mouse.
	 */
	private void questTooltip()
	{
		Widget root = client.getWidget(InterfaceID.Questlist.UNIVERSE);
		if (root == null || root.isHidden())
		{
			return;
		}
		net.runelite.api.Point m = client.getMouseCanvasPosition();
		Point mouse = new Point(m.getX(), m.getY());
		if (!root.getBounds().contains(mouse))
		{
			return;
		}
		Widget hit = textUnder(root, mouse, 0);
		if (hit != null)
		{
			long gp = achievements.questPayout(hit.getText());
			if (gp >= 0)
			{
				tooltipManager.add(new Tooltip(text(gp)));
			}
		}
	}

	private static Widget[][] groups(Widget w)
	{
		return new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()};
	}

	/** the visible text widget at the mouse whose text is a quest we pay for (deepest first) */
	private Widget textUnder(Widget w, Point mouse, int depth)
	{
		if (w == null || w.isSelfHidden() || depth > 8)
		{
			return null;
		}
		for (Widget[] group : groups(w))
		{
			if (group == null)
			{
				continue;
			}
			for (Widget c : group)
			{
				Widget r = textUnder(c, mouse, depth + 1);
				if (r != null)
				{
					return r;
				}
			}
		}
		String t = w.getText();
		if (t != null && !t.isEmpty() && w.getBounds().contains(mouse) && achievements.questPayout(t) >= 0)
		{
			return w;
		}
		return null;
	}

	private void clogTooltip()
	{
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (items == null || items.isHidden())
		{
			return;
		}
		Widget[] kids = items.getDynamicChildren();
		if (kids == null)
		{
			return;
		}
		net.runelite.api.Point m = client.getMouseCanvasPosition();
		Point mouse = new Point(m.getX(), m.getY());
		for (Widget w : kids)
		{
			if (w == null || w.isHidden() || w.getItemId() <= 0 || !w.getBounds().contains(mouse))
			{
				continue;
			}
			// only what is actually visible in the scrolling list (the scroll viewport is the parent's bounds)
			if (!items.getBounds().contains(mouse))
			{
				return;
			}
			String name = itemManager.getItemComposition(itemManager.canonicalize(w.getItemId())).getName();
			long gp = achievements.clogPayout(name);
			if (gp >= 0)
			{
				tooltipManager.add(new Tooltip(text(gp)));
			}
			return;
		}
	}
}

package com.goldmanmode;

/**
 * A number that ticks up to its new value instead of jumping. Every increase takes {@link #DURATION_MS} to arrive,
 * starting from whatever is on screen at that moment (so quick successive gains just keep it climbing).
 * The first value, and any decrease, show at once.
 */
final class CountUp
{
	static final long DURATION_MS = 600;

	private boolean started;
	private double from;
	private long target;
	private long startedAt;

	/** Tell it the real value; call every frame (it only reacts when the value changed). */
	synchronized void update(long value, long nowMs)
	{
		if (!started || value < target)
		{
			started = true;
			from = value;
			target = value;
			startedAt = nowMs;
		}
		else if (value > target)
		{
			from = shown(nowMs);
			target = value;
			startedAt = nowMs;
		}
	}

	/** The value to draw now. */
	synchronized long current(long nowMs)
	{
		return Math.round(shown(nowMs));
	}

	/** Forget everything, so the next value shows at once (after a logout, say). */
	synchronized void reset()
	{
		started = false;
	}

	private double shown(long nowMs)
	{
		if (!started)
		{
			return 0;
		}
		double t = (nowMs - startedAt) / (double) DURATION_MS;
		if (t >= 1)
		{
			return target;
		}
		if (t <= 0)
		{
			return from;
		}
		return from + (target - from) * t;
	}
}

