		boolean lastDone;

		Diary(String area, String tier, int countVarbit, int doneVarbit, int doneValue)
		{
			this.area = area;
			this.tier = tier;
			this.countVarbit = countVarbit;
			this.doneVarbit = doneVarbit;
			this.doneValue = doneValue;
