	/** Counts and done flags are given easy, medium, hard, elite; each flag is 1 when done. */
	private void diary(String area, int c1, int c2, int c3, int c4, int d1, int d2, int d3, int d4)
	{
		diary(area, c1, c2, c3, c4, d1, d2, d3, d4, 1, 1, 1, 1);
	}

	private void diary(String area, int c1, int c2, int c3, int c4, int d1, int d2, int d3, int d4, int v1, int v2, int v3, int v4)
	{
		String[] tier = {"easy", "medium", "hard", "elite"};
		int[] c = {c1, c2, c3, c4}, d = {d1, d2, d3, d4}, v = {v1, v2, v3, v4};
		for (int i = 0; i < 4; i++)
		{
			diaries.add(new Diary(area, tier[i], c[i], d[i], v[i]));
		}
	}

	/** Forget what you had: call whenever you leave the game, so the next login is looked at afresh. */
	public void reset()
	{
		baselined = false;
		ticksSinceLogin = 0;
	}

	// ------------------------------------------------------------------ diaries and combat achievement tiers

	public void onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (!baselined)
		{
			if (++ticksSinceLogin >= BASELINE_DELAY)
			{
				baseline();
			}
			return;
		}
		scanMessageBoxes();
		for (Diary d : diaries)
		{
			int count = client.getVarbitValue(d.countVarbit);
			if (count > d.lastCount)
			{
				int tasks = count - d.lastCount;
				Payouts.Tier t = payouts.diary(d.tier);
				if (t != null)
				{
					announceIf(state.award(null, state.scaled(GoldmanState.Payout.DIARIES, t.task * tasks)),
						diaryTasksText(tasks, d.tier, d.area));
				}
			}
			d.lastCount = count;
			boolean done = client.getVarbitValue(d.doneVarbit) >= d.doneValue;
			if (done && !d.lastDone)
			{
				Payouts.Tier t = payouts.diary(d.tier);
				if (t != null)
				{
					announceIf(state.award(d.claimKey(), state.scaled(GoldmanState.Payout.DIARIES, t.bonus)), "completing the " + d.tier + " " + d.area + " diary");
				}
			}
			d.lastDone = done;
		}
		payCombatTiers();
	}

	private void baseline()
	{
		List<String> have = new ArrayList<>();
		for (Diary d : diaries)
		{
			d.lastCount = client.getVarbitValue(d.countVarbit);
			d.lastDone = client.getVarbitValue(d.doneVarbit) >= d.doneValue;
			if (d.lastDone)
			{
				have.add(d.claimKey());
			}
		}
		int points = client.getVarbitValue(VarbitID.CA_POINTS);
		for (int i = 0; i < CA_TIERS.length; i++)
		{
			int need = client.getVarbitValue(CA_THRESHOLD[i]);
			if (need > 0 && points >= need)
			{
				have.add("a:" + CA_TIERS[i]);
			}
		}
		state.claimQuietly(have);
		baselined = true;
	}

	/** A combat achievement tier is complete once your points reach the points that unlock it. */
	private void payCombatTiers()
	{
		int points = client.getVarbitValue(VarbitID.CA_POINTS);
		for (int i = 0; i < CA_TIERS.length; i++)
		{
			int need = client.getVarbitValue(CA_THRESHOLD[i]);
			if (need > 0 && points >= need)
			{
				payCombatTier(CA_TIERS[i]);
			}
		}
	}

	/** Pay a combat achievement tier's bonus (once). */
	private void payCombatTier(String tier)
	{
		Payouts.Tier t = payouts.combat(tier);
		if (t == null)
		{
			log.info("Combat achievement tier not in the payout list: {}", tier);
			return;
		}
		announceIf(state.award("a:" + tier, state.scaled(GoldmanState.Payout.COMBAT_ACHIEVEMENTS, t.bonus)), "completing the " + tier + " combat achievements tier");
	}

	/** Pay a diary tier's bonus (once) when the game announces that every task of that tier in the area is done. */
	private void payDiaryTier(String tier, String area)
	{
		String want = areaKey(area);
		for (Diary d : diaries)
		{
			if (d.tier.equals(tier) && areaKey(d.area).equals(want))
			{
				Payouts.Tier t = payouts.diary(d.tier);
				if (t != null)
				{
					announceIf(state.award(d.claimKey(), state.scaled(GoldmanState.Payout.DIARIES, t.bonus)), "completing the " + d.tier + " " + d.area + " diary");
				}
				d.lastDone = true;
				return;
			}
		}
		log.info("Diary completion message for an area or tier we don't know: {} {}", tier, area);
	}

	/** The diary "Congratulations!" box is a plain message box: read it while it is open (paying is once only, so every tick is fine). */
	private void scanMessageBoxes()
	{
		for (int group : MESSAGE_BOX_GROUPS)
		{
			for (int child = 0; child <= 4; child++)
			{
				Widget w = client.getWidget(group, child);
				if (w == null || w.isHidden() || w.getText() == null || w.getText().isEmpty())
				{
					continue;
				}
				String[] done = parseDiaryTierDone(w.getText());
				if (done != null)
				{
					payDiaryTier(done[0], done[1]);
				}
			}
		}
	}

	/** an area's name without case, "and" versus "&", spaces or punctuation, so "Lumbridge & Draynor" matches however the game writes it */
	static String areaKey(String area)
	{
		return area.toLowerCase(Locale.ROOT).replace("&amp;", "&").replace(" and ", " & ").replaceAll("[^a-z]", "");
	}

	/** message text without colour tags, line breaks (as spaces), non-breaking spaces or "&amp;" */
	private static String plain(String message)
	{
		return Text.removeTags(message.replaceAll("(?i)<br\\s*/?>", " ")).replace('\u00a0', ' ').replace("&amp;", "&")
			.replaceAll("\\s+", " ").trim();
	}

	/** The tier a "completed enough Combat Achievement tasks to unlock ... Tier rewards" message names (lower case), or null. */
	static String parseCombatTierUnlock(String message)
	{
		Matcher m = COMBAT_TIER_UNLOCK.matcher(plain(message));
		return m.matches() ? m.group(1).toLowerCase(Locale.ROOT) : null;
	}

	/** {tier, area} from "You have completed all of the easy tasks in the Lumbridge & Draynor area", or null if it is something else. */
	static String[] parseDiaryTierDone(String message)
	{
		Matcher m = DIARY_TIER_DONE.matcher(plain(message));
		return m.matches() ? new String[]{m.group(1).toLowerCase(Locale.ROOT), m.group(2).trim()} : null;
	}

	// ------------------------------------------------------------------ chat messages: combat tasks and collection log

	/** What a combat task message says: {tier, task}, or null if the message is something else. */
	static String[] parseCombatTask(String message)
	{
		Matcher m = COMBAT_TASK.matcher(Text.removeTags(message).replace('\u00a0', ' ').trim());
		return m.matches() ? new String[]{m.group(1).toLowerCase(Locale.ROOT), m.group(2).trim()} : null;
	}

	/** The item a collection log message announces, or null if the message is something else. */
	static String parseCollectionLogItem(String message)
	{
		Matcher m = CLOG_ITEM.matcher(Text.removeTags(message).trim());
		return m.matches() ? m.group(1).trim() : null;
	}

	public void onChatMessage(ChatMessageType type, String message)
	{
		if (message == null)
		{
			return;
		}
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.ENGINE)
		{
			if (message.toLowerCase(Locale.ROOT).contains("combat task"))
			{
				log.info("Ignored a {} message about a combat task: {}", type, message);
			}
			return;
		}
		String unlockedTier = parseCombatTierUnlock(message);
		if (unlockedTier != null)
		{
			payCombatTier(unlockedTier);
			return;
		}
		String[] diaryDone = parseDiaryTierDone(message);
		if (diaryDone != null)
		{
			payDiaryTier(diaryDone[0], diaryDone[1]);
			return;
		}
		String[] task = parseCombatTask(message);
		if (task != null)
		{
			Payouts.Tier t = payouts.combat(task[0]);
			if (t == null)
			{
				log.info("Combat task tier not in the payout list: {}", message);
			}
			else
			{
				long paid = state.award("t:" + Payouts.normalise(task[1]), state.scaled(GoldmanState.Payout.COMBAT_ACHIEVEMENTS, t.task));
				if (paid == 0)
				{
					log.info("Combat task not paid (already paid before?): {}", message);
				}
				announceIf(paid, "the " + task[0] + " combat task: " + task[1]);
			}
			return;
		}
		String item = parseCollectionLogItem(message);
		if (item != null)
		{
			long gp = payouts.clogItem(item);
			if (gp < 0)
			{
				log.info("Collection log item not in the payout list: {}", item);
				return;
			}
			announceIf(state.award("c:" + Payouts.normalise(item), state.scaled(GoldmanState.Payout.COLLECTION_LOG, gp)), "the collection log item: " + item);
		}
	}

	// ------------------------------------------------------------------ quests

	/** The quest complete scroll has opened. Its text is filled in a moment later, so look for it for a few ticks. */
	public void onWidgetLoaded(int groupId)
	{
		if (groupId != InterfaceID.QUESTSCROLL)
		{
			return;
		}
		final int[] tries = {0};
		clientThread.invokeLater(() ->
		{
			Widget title = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
			String text = title == null ? null : title.getText();
			if ((text == null || text.isEmpty()) && ++tries[0] < 5)
			{
				return false; // not filled in yet: look again next tick
			}
			if (text != null && !text.isEmpty())
			{
				payQuest(text);
			}
			return true;
		});
	}

	void payQuest(String text)
	{
		Payouts.QuestHit q = payouts.questIn(text);
		if (q == null)
		{
			log.info("Quest scroll not in the payout list: {}", text);
			return;
		}
		announceIf(state.award("q:" + q.name, state.scaled(GoldmanState.Payout.QUESTS, q.gp)), "completing the quest: " + questTitle(text, q.name));
	}

	/** the quest's name as the game spells it ("Dragon Slayer II"), picked out of text such as "You have completed Dragon Slayer II!" */
	static String questTitle(String text, String normalisedName)
	{
		String plain = Text.removeTags(text).trim();
		String pattern = Pattern.quote(normalisedName).replace(" ", "\\E\\s+\\Q").replace("'", "\\E['\u2018\u2019]\\Q");
		Matcher m = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE).matcher(plain);
		return m.find() ? m.group() : plain;
	}

	// ------------------------------------------------------------------ chat feedback

	/** "an easy Karamja diary task", "a hard Karamja diary task" or "3 easy Karamja diary tasks" */
	static String diaryTasksText(int tasks, String tier, String area)
	{
		String lead = tasks != 1 ? tasks + " " : ("aeiou".indexOf(Character.toLowerCase(tier.charAt(0))) >= 0 ? "an " : "a ");
		return lead + tier + " " + area + " diary task" + (tasks == 1 ? "" : "s");
	}

	private void announceIf(long gp, String what)
	{
		if (gp <= 0)
		{
			return;
		}
		log.info("Goldman GP +{} for {}", gp, what);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"<col=ffffff>Goldman Mode:</col> <col=ffff00>+" + QuantityFormatter.formatNumber(gp) + " gp for " + what + ".</col>", null);
	}
}

package com.goldmanmode;

import java.util.List;
import lombok.Getter;

/**
 * One unlockable map area, built from the shapes drawn on the Goldman area-drawing page.
 * Coordinates are OSRS world tiles (x east, y north). An area is made of one or more
 * parts; each part is an outer ring plus optional hole rings (even-odd fill).
 */
public class GoldmanArea
{
	@Getter
	private final String id;
	@Getter
	private final String name;
	@Getter
	private final int colourIndex;
	@Getter
	private final String notes;
	/** Every ring of every part, as [ [x,y], ... ] - used to draw the area on the world map. */
	@Getter
	private final List<double[][]> rings;
	/** The rings of each part (outer first, then holes) - used to rasterise it. */
	@Getter
	private final List<List<double[][]>> parts;
	@Getter
	private final int minX, minY, maxX, maxY;

	/** Packed tiles owned by this shape: (x << 16) | y. Filled in by AreaIndex. */
	@Getter
	private int[] tiles = new int[0];
	@Getter
	private int index = -1;

	/** Price in Goldman GP worked out by tools/price_areas.py, or -1 if the areas file has none. */
	@Getter
	private final long price;

	GoldmanArea(String id, String name, int colourIndex, String notes, List<List<double[][]>> parts)
	{
		this(id, name, colourIndex, notes, parts, -1);
	}

	GoldmanArea(String id, String name, int colourIndex, String notes, List<List<double[][]>> parts, long price)
	{
		this.price = price;
		this.id = id;
		this.name = name;
		this.colourIndex = colourIndex;
		this.notes = notes == null ? "" : notes;
		this.parts = parts;
		this.rings = new java.util.ArrayList<>();
		double x0 = Double.MAX_VALUE, y0 = Double.MAX_VALUE, x1 = -Double.MAX_VALUE, y1 = -Double.MAX_VALUE;
		for (List<double[][]> part : parts)
		{
			for (double[][] ring : part)
			{
				rings.add(ring);
				for (double[] p : ring)
				{
					x0 = Math.min(x0, p[0]);
					y0 = Math.min(y0, p[1]);
					x1 = Math.max(x1, p[0]);
					y1 = Math.max(y1, p[1]);
				}
			}
		}
		if (rings.isEmpty())
		{
			x0 = y0 = x1 = y1 = 0;
		}
		minX = (int) Math.floor(x0);
		minY = (int) Math.floor(y0);
		maxX = (int) Math.ceil(x1);
		maxY = (int) Math.ceil(y1);
	}

	void setTiles(int[] tiles, int index)
	{
		this.tiles = tiles;
		this.index = index;
	}

	/** Size in tiles (what the price is based on). */
	public int getSize()
	{
		return tiles.length;
	}

	/** A tile inside the area that is closest to its centre of mass (a good spot to centre the map on). */
	public int[] getLabelTile()
	{
		if (tiles.length == 0)
		{
			return new int[]{(minX + maxX) / 2, (minY + maxY) / 2};
		}
		double cx = 0, cy = 0;
		for (int t : tiles)
		{
			cx += t >>> 16;
			cy += t & 0xFFFF;
		}
		cx /= tiles.length;
		cy /= tiles.length;
		long best = Long.MAX_VALUE;
		int bx = 0, by = 0;
		for (int t : tiles)
		{
			int x = t >>> 16, y = t & 0xFFFF;
			long d = (long) ((x - cx) * (x - cx) + (y - cy) * (y - cy));
			if (d < best)
			{
				best = d;
				bx = x;
				by = y;
			}
		}
		return new int[]{bx, by};
	}
}

package com.goldmanmode;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.awt.geom.Area;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws a low barrier along the outside of every locked area: the line you are not supposed to cross. */
@Singleton
public class GoldmanBarrierOverlay extends Overlay
{
	private static final int HALF = Perspective.LOCAL_TILE_SIZE / 2;

	private final Client client;
	private final GoldmanState state;

	@Inject
	GoldmanBarrierOverlay(Client client, GoldmanState state)
	{
		this.client = client;
		this.state = state;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.UNDER_WIDGETS); // after the models are drawn; the code below decides per wall whether you are in front or behind
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || wv.getScene() == null)
		{
			return null;
		}
		AreaIndex index = state.getIndex();
		if (index.getAreas().isEmpty())
		{
			return null;
		}

		LocalPoint centre = LocalPoint.fromWorld(wv, me.getWorldLocation());
		if (centre == null)
		{
			centre = me.getLocalLocation();
		}
		final int cx = centre.getSceneX();
		final int cy = centre.getSceneY();
		final int reach = Settings.BARRIER_DISTANCE;
		final int fadeWidth = Math.max(1, Math.min(Settings.BARRIER_FADE_WIDTH, reach));
		final int r = reach + 1;
		final int plane = wv.getPlane();
		final boolean instanced = Instances.isInstanced(client);
		final int baseX = wv.getBaseX();
		final int baseY = wv.getBaseY();
		final int sizeX = Math.min(wv.getSizeX(), Constants.SCENE_SIZE);
		final int sizeY = Math.min(wv.getSizeY(), Constants.SCENE_SIZE);
		final int height = Settings.BARRIER_HEIGHT;
		// smooth position, so the fade changes continuously while you walk
		final LocalPoint me2 = me.getLocalLocation();

		// pulse: 1.0 at its brightest, (1 - strength) at its dimmest
		double strength = Settings.PULSE_STRENGTH / 100.0;
		double period = Math.max(300, Settings.PULSE_PERIOD_MS);
		double phase = (System.currentTimeMillis() % (long) period) / period;
		final double pulse = 1.0 - strength * (0.5 + 0.5 * Math.sin(phase * 2 * Math.PI));

		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		this.base = Settings.BARRIER_COLOUR;
		this.pulseNow = pulse;

		// Occlusion by your own character: where the barrier is BEHIND you (further from the camera)
		// your model's exact outline is cut out of it; where it is IN FRONT of you it is drawn over you.
		this.origClip = g.getClip();
		this.sil = null;
		this.silBounds = null;
		this.outsideBounds = null;
		this.layerG = null;
		double camX = client.getCameraX(), camY = client.getCameraY();
		double fx = me2.getX() - camX, fy = me2.getY() - camY;
		double fl = Math.sqrt(fx * fx + fy * fy);
		if (fl > 1)
		{
			this.camX = camX;
			this.camY = camY;
			this.fwdX = fx / fl;
			this.fwdY = fy / fl;
			this.playerDepth = fl;
			this.sil = silhouette(wv, me, plane);
			if (sil != null)
			{
				Rectangle sb = sil.getBounds();
				sb.grow(8, 8);
				sb = sb.intersection(new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));
				if (sb.isEmpty())
				{
					this.sil = null;
				}
				else
				{
					this.silBounds = sb;
					Area out = new Area(new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight()));
					out.subtract(new Area(sb));
					this.outsideBounds = out;
				}
			}
		}

		if (!instanced)
		{
			// the barrier follows the straight outline of each area (not tile edges), so diagonals are straight
			BarrierGeometry geo = index.getBarrier();
			final double ppx = baseX + me2.getX() / (double) Perspective.LOCAL_TILE_SIZE;
			final double ppy = baseY + me2.getY() / (double) Perspective.LOCAL_TILE_SIZE;
			final int maxLocalX = sizeX * Perspective.LOCAL_TILE_SIZE, maxLocalY = sizeY * Perspective.LOCAL_TILE_SIZE;
			for (int rx = (int) Math.floor(ppx - reach) >> 6; rx <= (int) Math.floor(ppx + reach) >> 6; rx++)
			{
				for (int ry = (int) Math.floor(ppy - reach) >> 6; ry <= (int) Math.floor(ppy + reach) >> 6; ry++)
				{
					List<BarrierGeometry.Piece> pieces = geo.region(rx, ry);
					if (pieces == null)
					{
						continue;
					}
					for (BarrierGeometry.Piece pc : pieces)
					{
						if (!state.isLockedBorder(pc))
						{
							continue;
						}
						int ax = (int) Math.round((pc.x1 - baseX) * Perspective.LOCAL_TILE_SIZE);
						int ay = (int) Math.round((pc.y1 - baseY) * Perspective.LOCAL_TILE_SIZE);
						int bx = (int) Math.round((pc.x2 - baseX) * Perspective.LOCAL_TILE_SIZE);
						int by = (int) Math.round((pc.y2 - baseY) * Perspective.LOCAL_TILE_SIZE);
						if (ax < 0 || ay < 0 || bx < 0 || by < 0 || ax > maxLocalX || bx > maxLocalX || ay > maxLocalY || by > maxLocalY)
						{
							continue;
						}
						wall(g, me2, plane, ax, ay, bx, by, height, reach, fadeWidth);
					}
				}
			}
		}

		g.setClip(origClip);
		if (layerG != null)
		{
			// cut your model's silhouette out of the "behind you" layer, then lay it on the screen
			layerG.setComposite(AlphaComposite.DstOut);
			layerG.setColor(Color.WHITE);
			layerG.fill(sil);
			layerG.dispose();
			layerG = null;
			int w = silBounds.width, h = silBounds.height;
			g.drawImage(layer, silBounds.x, silBounds.y, silBounds.x + w, silBounds.y + h, 0, 0, w, h, null);
		}
		if (aa != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		}
		return null;
	}

	// ---- your character's silhouette, built from the real model triangles ----

	private int[] px = new int[0], py = new int[0];

	private Path2D.Double silhouette(WorldView wv, Player me, int plane)
	{
		Model model = me.getModel();
		LocalPoint ml = me.getLocalLocation();
		if (model == null || ml == null)
		{
			return null;
		}
		int n = model.getVerticesCount();
		int fc = model.getFaceCount();
		if (n <= 0 || fc <= 0)
		{
			return null;
		}
		if (px.length < n)
		{
			px = new int[n];
			py = new int[n];
		}
		int z = Perspective.getFootprintTileHeight(client, ml, plane, me.getFootprintSize()) - me.getAnimationHeightOffset();
		// same call RuneLite's own model outline uses (note the Y/Z swap)
		Perspective.modelToCanvas(client, wv, n, ml.getX(), ml.getY(), z, me.getCurrentOrientation(),
			model.getVerticesX(), model.getVerticesZ(), model.getVerticesY(), px, py);
		int[] i1 = model.getFaceIndices1(), i2 = model.getFaceIndices2(), i3 = model.getFaceIndices3();
		byte[] tr = model.getFaceTransparencies();
		Path2D.Double path = new Path2D.Double(Path2D.WIND_NON_ZERO);
		boolean any = false;
		for (int f = 0; f < fc; f++)
		{
			if (tr != null && (tr[f] & 0xFF) >= 250)
			{
				continue; // invisible face
			}
			int a = i1[f], b = i2[f], c = i3[f];
			if (py[a] == Integer.MIN_VALUE || py[b] == Integer.MIN_VALUE || py[c] == Integer.MIN_VALUE)
			{
				continue;
			}
			long cross = (long) (px[b] - px[a]) * (py[c] - py[a]) - (long) (px[c] - px[a]) * (py[b] - py[a]);
			if (cross == 0)
			{
				continue;
			}
			path.moveTo(px[a], py[a]);
			if (cross > 0)
			{
				path.lineTo(px[b], py[b]);
				path.lineTo(px[c], py[c]);
			}
			else
			{
				path.lineTo(px[c], py[c]);
				path.lineTo(px[b], py[b]);
			}
			path.closePath();
			any = true;
		}
		return any ? path : null;
	}

	// ---- offscreen layer for the parts of the barrier that are behind you ----

	private BufferedImage layer;
	private Graphics2D layerG;

	private Graphics2D layerGraphics()
	{
		if (layerG == null)
		{
			int w = silBounds.width, h = silBounds.height;
			if (layer == null || layer.getWidth() < w || layer.getHeight() < h)
			{
				layer = new BufferedImage(Math.max(w, layer == null ? 0 : layer.getWidth()),
					Math.max(h, layer == null ? 0 : layer.getHeight()), BufferedImage.TYPE_INT_ARGB);
			}
			Graphics2D lg = layer.createGraphics();
			lg.setComposite(AlphaComposite.Clear);
			lg.fillRect(0, 0, layer.getWidth(), layer.getHeight());
			lg.setComposite(AlphaComposite.SrcOver);
			lg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			lg.translate(-silBounds.x, -silBounds.y);
			// the layer image can be bigger than this frame's box (it is reused): only ever use the box
			lg.clipRect(silBounds.x, silBounds.y, w, h);
			layerG = lg;
		}
		return layerG;
	}

	private java.awt.Shape origClip;
	private Path2D.Double sil;
	private Rectangle silBounds;
	private Area outsideBounds;
	private double playerDepth = Double.NaN, camX, camY, fwdX, fwdY;
	private Color base = Color.RED;
	private double pulseNow = 1;

	private static Color alpha(Color c, double a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), (int) Math.max(0, Math.min(255, Math.round(a))));
	}

	private void wall(Graphics2D g, LocalPoint me, int plane, int ax, int ay, int bx, int by, int height, int reach, int fadeWidth)
	{
		// distance from the player to the middle of this edge, in tiles
		double dx = (ax + bx) / 2.0 - me.getX();
		double dy = (ay + by) / 2.0 - me.getY();
		double d = Math.sqrt(dx * dx + dy * dy) / Perspective.LOCAL_TILE_SIZE;
		// fully visible up to (reach - fadeWidth), fading to nothing at reach
		double fade = Math.max(0, Math.min(1, (reach - d) / fadeWidth));
		if (fade <= 0.01)
		{
			return;
		}
		int ha = Perspective.getTileHeight(client, new LocalPoint(ax, ay, WorldView.TOPLEVEL), plane);
		int hb = Perspective.getTileHeight(client, new LocalPoint(bx, by, WorldView.TOPLEVEL), plane);
		// in OSRS, smaller z is higher up
		Point a0 = Perspective.localToCanvas(client, ax, ay, ha);
		Point b0 = Perspective.localToCanvas(client, bx, by, hb);
		Point b1 = Perspective.localToCanvas(client, bx, by, hb - height);
		Point a1 = Perspective.localToCanvas(client, ax, ay, ha - height);
		if (a0 == null || b0 == null || a1 == null || b1 == null)
		{
			return;
		}
		double k = fade * pulseNow;
		double A = base.getAlpha();

		// glowing wall: strongest at the top rail, fading towards the ground
		Path2D.Double quad = new Path2D.Double();
		quad.moveTo(a0.getX(), a0.getY());
		quad.lineTo(b0.getX(), b0.getY());
		quad.lineTo(b1.getX(), b1.getY());
		quad.lineTo(a1.getX(), a1.getY());
		quad.closePath();
		// is this bit of barrier further from the camera than the player? then the player is drawn over it
		boolean behind = false;
		if (sil != null)
		{
			double wDepth = ((ax + bx) / 2.0 - camX) * fwdX + ((ay + by) / 2.0 - camY) * fwdY;
			if (wDepth > playerDepth + 8)
			{
				java.awt.geom.Rectangle2D qb = quad.getBounds2D();
				qb.setRect(qb.getX() - 6, qb.getY() - 6, qb.getWidth() + 12, qb.getHeight() + 12);
				behind = qb.intersects(silBounds);
			}
		}
		g.setClip(origClip);
		if (!behind)
		{
			paint(g, quad, a0, b0, a1, b1, k, A);
			return;
		}
		// outside the player's bounding box: draw normally; inside it: into the layer that gets the cut-out
		g.clip(outsideBounds);
		paint(g, quad, a0, b0, a1, b1, k, A);
		g.setClip(origClip);
		paint(layerGraphics(), quad, a0, b0, a1, b1, k, A);
	}

	private void paint(Graphics2D g, Path2D.Double quad, Point a0, Point b0, Point a1, Point b1, double k, double A)
	{
		float mx = (a1.getX() + b1.getX()) / 2f, my = (a1.getY() + b1.getY()) / 2f;
		float gx = (a0.getX() + b0.getX()) / 2f, gy = (a0.getY() + b0.getY()) / 2f;
		if (Math.abs(my - gy) < 1f)
		{
			gy = my + 1f;
		}
		g.setPaint(new GradientPaint(mx, my, alpha(base, A * 0.95 * k), gx, gy, alpha(base, A * 0.35 * k)));
		g.fill(quad);

		// glowing top rail: wide soft halo, then a bright core
		Line2D.Double rail = new Line2D.Double(a1.getX(), a1.getY(), b1.getX(), b1.getY());
		g.setStroke(new BasicStroke(9f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(base, A * 0.10 * k));
		g.draw(rail);
		g.setStroke(new BasicStroke(5f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(base, A * 0.22 * k));
		g.draw(rail);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(alpha(lighten(base), Math.min(255, (A + 100) * k)));
		g.draw(rail);
	}

	private static Color lighten(Color c)
	{
		return new Color(Math.min(255, c.getRed() + 30), Math.min(255, c.getGreen() + 60), Math.min(255, c.getBlue() + 60), c.getAlpha());
	}
}

package com.goldmanmode;

import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;

/** Stops walking to, and interacting with, anything that stands inside a locked area. */
@Singleton
class GoldmanClickBlocker
{
	private final Client client;
	private final ClientThread clientThread;
	private final MouseManager mouseManager;
	private final GoldmanModeConfig config;
	private final GoldmanState state;
	private final GoldmanMapWindow mapWindow;

	/** Minimap geometry refreshed every client tick, so the mouse thread can use it without touching the game. */
	private volatile MinimapFrame frame;
	private volatile WorldPoint walkTarget;
	private volatile long lastWarn;

	@Inject
	GoldmanClickBlocker(Client client, ClientThread clientThread, MouseManager mouseManager, GoldmanModeConfig config,
		GoldmanState state, GoldmanMapWindow mapWindow)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.mouseManager = mouseManager;
		this.config = config;
		this.state = state;
		this.mapWindow = mapWindow;
	}

	void startUp()
	{
		mouseManager.registerMouseListener(minimapBlocker);
	}

	void shutDown()
	{
		mouseManager.unregisterMouseListener(minimapBlocker);
		frame = null;
	}

	void onClientTick()
	{
		Player me = client.getLocalPlayer();
		frame = me == null || client.getGameState() != GameState.LOGGED_IN ? null : computeFrame(me);
	}

	/** Every time "Walk here" is offered, remember which tile it would walk to. */
	void onMenuEntryAdded(MenuEntryAdded e)
	{
		if (e.getMenuEntry().getType() == MenuAction.WALK)
		{
			walkTarget = currentWalkTarget();
		}
	}

	void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (!config.blockLockedClicks() || Instances.isInstanced(client) || e.isConsumed())
		{
			return;
		}
		WorldPoint target = targetOf(e);
		if (target == null)
		{
			return;
		}
		GoldmanArea area = blockingArea(target.getX(), target.getY());
		if (area == null)
		{
			return;
		}
		e.consume();
		warnLocked(area);
	}

	/**
	 * The client walks to a minimap click by itself (no menu action, so no MenuOptionClicked we could cancel), so the
	 * only way to stop it is to swallow the mouse click before the game sees it.
	 */
	private final MouseAdapter minimapBlocker = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			return block(e, true);
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			return block(e, false);
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			return block(e, false);
		}

		private MouseEvent block(MouseEvent e, boolean warn)
		{
			if (e.getButton() != MouseEvent.BUTTON1 || !config.blockLockedClicks() || mapWindow.isOpen())
			{
				return e; // while the map is open it has the mouse (its buttons sit where the minimap is)
			}
			WorldPoint tile = tileAt(frame, e.getX(), e.getY());
			GoldmanArea area = tile == null ? null : blockingArea(tile.getX(), tile.getY());
			if (area == null)
			{
				return e;
			}
			e.consume();
			if (warn)
			{
				warnLocked(area);
			}
			return e;
		}
	};

	/**
	 * The locked area that stops you using this tile, or null. That is the area the tile is in, or a locked area
	 * whose barrier cuts through the tile (so you can't stand half out of bounds on a diagonal border).
	 */
	private GoldmanArea blockingArea(int x, int y)
	{
		AreaIndex idx = state.getIndex();
		GoldmanArea in = idx.areaAt(x, y);
		if (in != null && !state.isUnlocked(in))
		{
			return in;
		}
		List<BarrierGeometry.Piece> pieces = idx.getBarrier().crossing(x, y);
		if (pieces != null)
		{
			for (BarrierGeometry.Piece pc : pieces)
			{
				if (state.isLockedBorder(pc))
				{
					return idx.getAreas().get(pc.ring);
				}
			}
		}
		return null;
	}

	private void warnLocked(GoldmanArea area)
	{
		long now = System.currentTimeMillis();
		if (now - lastWarn > 1500)
		{
			lastWarn = now;
			clientThread.invoke(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"<col=ffffff>Goldman Mode:</col> <col=ff0000>" + area.getName() + " has not been unlocked yet.</col>", null));
		}
	}

	/** The tile an interaction is aimed at, or null if it is not about a place in the world. */
	private WorldPoint targetOf(MenuOptionClicked e)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}
		switch (e.getMenuAction())
		{
			case WALK:
			{
				// RuneLite does not put the destination in the click event. For a plain left click the mouse is
				// still over the target (viewport tile or minimap), so look at it now; if a right-click menu is
				// open, use what was under the mouse when it was built.
				WorldPoint fresh = client.isMenuOpen() ? null : currentWalkTarget();
				return fresh != null ? fresh : walkTarget;
			}
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case ITEM_USE_ON_NPC:
			case WIDGET_TARGET_ON_NPC:
			{
				NPC npc = wv.npcs().byIndex(e.getId());
				return npc == null ? null : npc.getWorldLocation();
			}
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
			case ITEM_USE_ON_PLAYER:
			case WIDGET_TARGET_ON_PLAYER:
			{
				Player p = wv.players().byIndex(e.getId());
				return p == null ? null : p.getWorldLocation();
			}
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case ITEM_USE_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case ITEM_USE_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_GROUND_ITEM:
				return WorldPoint.fromScene(wv, e.getParam0(), e.getParam1(), wv.getPlane());
			default:
				return null; // examine, cancel, inventory, interface clicks etc. are always allowed
		}
	}

	private WorldPoint currentWalkTarget()
	{
		WorldView wv = client.getTopLevelWorldView();
		Player me = client.getLocalPlayer();
		if (wv == null || me == null)
		{
			return null;
		}
		Point mouse = client.getMouseCanvasPosition();
		WorldPoint onMinimap = mouse == null ? null : tileAt(computeFrame(me), mouse.getX(), mouse.getY());
		if (onMinimap != null)
		{
			return onMinimap;
		}
		Tile t = wv.getSelectedSceneTile();
		return t == null ? null : WorldPoint.fromLocalInstance(client, t.getLocalLocation());
	}

	/** One snapshot of how the minimap maps tiles to pixels: c0 is the player's tile, u one tile east, v one north. */
	private static final class MinimapFrame
	{
		double c0x, c0y, ux, uy, vx, vy;
		WorldPoint base;
		Rectangle bounds;
	}

	private MinimapFrame computeFrame(Player me)
	{
		LocalPoint here = me.getLocalLocation();
		if (here == null || Instances.isInstanced(client))
		{
			return null;
		}
		Rectangle bounds = null;
		for (int id : new int[]{InterfaceID.ToplevelOsrsStretch.MINIMAP,
			InterfaceID.ToplevelPreEoc.MINIMAP, InterfaceID.Toplevel.MINIMAP})
		{
			Widget w = client.getWidget(id);
			if (w != null && !w.isHidden() && w.getBounds().width > 0)
			{
				bounds = w.getBounds();
				break;
			}
		}
		if (bounds == null)
		{
			return null;
		}
		int cx = (here.getX() >> 7 << 7) + 64, cy = (here.getY() >> 7 << 7) + 64;
		Point c0 = Perspective.localToMinimap(client, new LocalPoint(cx, cy, WorldView.TOPLEVEL));
		double[] u = minimapStep(c0, cx, cy, 1, 0);
		double[] v = minimapStep(c0, cx, cy, 0, 1);
		if (u == null || v == null || Math.abs(u[0] * v[1] - u[1] * v[0]) < 1e-6)
		{
			return null;
		}
		MinimapFrame f = new MinimapFrame();
		f.c0x = c0.getX();
		f.c0y = c0.getY();
		f.ux = u[0];
		f.uy = u[1];
		f.vx = v[0];
		f.vy = v[1];
		f.bounds = bounds;
		f.base = WorldPoint.fromLocalInstance(client, new LocalPoint(cx, cy, WorldView.TOPLEVEL));
		return f;
	}

	/** The tile under canvas point (mx, my) if that point is on the minimap, else null. */
	private static WorldPoint tileAt(MinimapFrame f, int mx, int my)
	{
		if (f == null)
		{
			return null;
		}
		double hw = f.bounds.width / 2.0, hh = f.bounds.height / 2.0;
		double nx = (mx - f.bounds.getCenterX()) / hw, ny = (my - f.bounds.getCenterY()) / hh;
		if (nx * nx + ny * ny > 1)
		{
			return null;
		}
		double px = mx - f.c0x, py = my - f.c0y;
		double det = f.ux * f.vy - f.uy * f.vx;
		int dx = (int) Math.round((px * f.vy - py * f.vx) / det);
		int dy = (int) Math.round((f.ux * py - f.uy * px) / det);
		return new WorldPoint(f.base.getX() + dx, f.base.getY() + dy, f.base.getPlane());
	}

	/** Pixels moved on the minimap per tile in direction (tx, ty), measured over up to 16 tiles to beat rounding. */
	private double[] minimapStep(Point c0, int cx, int cy, int tx, int ty)
	{
		if (c0 == null)
		{
			return null;
		}
		for (int k : new int[]{16, 8, 4, 2, 1})
		{
			Point p = Perspective.localToMinimap(client,
				new LocalPoint(cx + tx * k * Perspective.LOCAL_TILE_SIZE, cy + ty * k * Perspective.LOCAL_TILE_SIZE, WorldView.TOPLEVEL));
			if (p != null)
			{
				return new double[]{(p.getX() - c0.getX()) / (double) k, (p.getY() - c0.getY()) / (double) k};
			}
		}
		return null;
	}
}

package com.goldmanmode;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

/** The Goldman GP balance on screen: "Goldman GP" on the first row, the amount on the second, both centred.
 * The amount ticks up over 0.6 seconds whenever it goes up. */
@Singleton
public class GoldmanGpOverlay extends OverlayPanel
{
	private final Client client;
	private final GoldmanState state;
	private final GoldmanModeConfig config;
	private final CountUp shown = new CountUp();

	@Inject
	GoldmanGpOverlay(Client client, GoldmanState state, GoldmanModeConfig config)
	{
		this.client = client;
		this.state = state;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showGpOverlay() || client.getGameState() != GameState.LOGGED_IN)
		{
			shown.reset(); // the first number after logging in (or turning the overlay on) shows at once
			return null;
		}
		long now = System.currentTimeMillis();
		shown.update(state.getBalance(), now);
		panelComponent.setPreferredSize(new Dimension(110, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text("Goldman GP").color(Color.WHITE).build());
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(QuantityFormatter.formatNumber(shown.current(now))).color(Color.YELLOW).build());
		return super.render(g);
	}
}

package com.goldmanmode;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the Goldman world map over the whole game window while it is open. */
@Singleton
public class GoldmanMapOverlay extends Overlay
{
	private final Client client;
	private volatile GoldmanMapView view;

	@Inject
	GoldmanMapOverlay(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(PRIORITY_HIGHEST);
	}

	void setView(GoldmanMapView view)
	{
		this.view = view;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		GoldmanMapView v = view;
		if (v == null || !v.isVisible())
		{
			return null;
		}
		v.render(g, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

package com.goldmanmode;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * The map drawn over the whole game view: smooth zoom and scrolling, area borders and a price tooltip. While open it
 * takes clicks, scrolling and key presses. Events arrive on the AWT thread and drawing on the client thread, so everything
 * here is synchronized.
 */
final class GoldmanMapView
{
	/** What the map needs to know about the game and the settings. */
	interface Host
	{
		AreaIndex areas();

		boolean isUnlocked(GoldmanArea a);

		boolean isFree(GoldmanArea a);

		long cost(GoldmanArea a);

		long balance();

		/** the player's tile, or null when not in the surface world */
		WorldPoint player();

		/** buy (unlock) an area with the Goldman GP balance; called from the AWT thread */
		void buy(GoldmanArea a);
	}

	private static final Font BASE_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
	private static final Color OCEAN = new Color(12, 14, 20);
	private static final double MAX_SCALE = 10;
	/** how much one notch of the mouse wheel zooms (natural log) */
	private static final double ZOOM_PER_NOTCH = 0.021;
	private static final Color LOCKED_FILL = new Color(220, 40, 40, 112);
	private static final Color LOCKED_FILL_HOVER = new Color(255, 70, 70, 160);
	private static final Color UNLOCKED_FILL_HOVER = new Color(255, 255, 255, 80);
	private static final Color LOCKED_LINE = new Color(255, 64, 64, 240);
	private static final Color UNLOCKED_LINE = new Color(90, 210, 120, 215);
	private static final Color HOVER_LINE = new Color(255, 255, 255, 250);
	private static final Color BORDER = new Color(0x14, 0x14, 0x14); // #141414, opaque: tooltip border
	private static final Color PANEL = new Color(0x14, 0x14, 0x14, 0xB7); // #B7141414 (ARGB): tooltip background
	private static final Color TIP_RED = new Color(0xff, 0x00, 0x00); // #ff0000: unaffordable price in the tooltip
	private static final Color YELLOW = new Color(255, 255, 0);
	private static final Color GREEN = new Color(0, 255, 0);
	private static final Color RED = new Color(255, 51, 51);
	/** how long the map takes to fade in and out, ms */
	private static final double FADE_MS = 160;
	private static final BitmapFont FONT = BitmapFont.load();

	private final Host host;
	private final MapTiles tiles;
	private final MapRegions regions;
	private final Runnable onClose;
	private final MapViewport vp = new MapViewport();
	private final double[] world;

	private boolean open;
	private boolean initialised;

	// animation state
	private double targetScale = 1;
	private double anchorWx, anchorWy, anchorSx, anchorSy;
	private long flyStart;
	private double flyFromX, flyFromY, flyFromScale, flyToX, flyToY, flyToScale;
	private boolean flying;
	private long lastFrame = System.nanoTime();
	private double alpha; // 0 = gone, 1 = fully shown; follows open with a short fade
	private long alphaNs = System.nanoTime();
	private boolean memoryHeld;

	// mouse
	private int mouseX = -1, mouseY = -1;
	private boolean dragging;
	private int pressX, pressY;
	private boolean dragMoved; // the press turned into a drag, so it is not a click
	/** the area whose "Confirm unlock" tooltip is showing after a first click */
	private GoldmanArea confirming;
	private int lastDragX, lastDragY;
	private long lastDragTime;

	private final Map<GoldmanArea, Path2D[]> paths = new HashMap<>();
	GoldmanMapView(Host host, MapTiles tiles, MapRegions regions, Runnable onClose)
	{
		this.host = host;
		this.tiles = tiles;
		this.regions = regions;
		this.onClose = onClose;
		this.world = regions.worldBounds();
	}

	// ------------------------------------------------------------------ open / close

	synchronized boolean isOpen()
	{
		return open;
	}

	synchronized void open()
	{
		open = true;
		lastFrame = System.nanoTime();
		alphaNs = lastFrame;
		memoryHeld = true;
	}

	/** forget where the map was looking: the next open starts from the whole map again (called on logout) */
	synchronized void resetView()
	{
		initialised = false;
	}

	/** open, or still fading out: the overlay keeps drawing until this is false */
	synchronized boolean isVisible()
	{
		return open || alpha > 0;
	}

	synchronized void close()
	{
		open = false;
		confirming = null;
		alphaNs = System.nanoTime();
		dragging = false;
		flying = false;
	}

	// ------------------------------------------------------------------ input

	final MouseAdapter mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			synchronized (GoldmanMapView.this)
			{
				mouseX = e.getX();
				mouseY = e.getY();
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					dragging = true;
					dragMoved = false;
					pressX = e.getX();
					pressY = e.getY();
					flying = false;
					lastDragX = e.getX();
					lastDragY = e.getY();
					lastDragTime = System.nanoTime();
				}
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			GoldmanArea toBuy = null;
			synchronized (GoldmanMapView.this)
			{
				if (dragging)
				{
					dragging = false; // the map stops where you let go
					if (e.getButton() == MouseEvent.BUTTON1 && !dragMoved)
					{
						toBuy = clicked(e.getX(), e.getY());
					}
				}
			}
			if (toBuy != null)
			{
				host.buy(toBuy);
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent e)
		{
			synchronized (GoldmanMapView.this)
			{
				mouseX = e.getX();
				mouseY = e.getY();
				if (dragging)
				{
					if (Math.abs(e.getX() - pressX) > 3 || Math.abs(e.getY() - pressY) > 3)
					{
						dragMoved = true;
						confirming = null;
					}
					long now = System.nanoTime();
					int dx = e.getX() - lastDragX, dy = e.getY() - lastDragY;
					lastDragX = e.getX();
					lastDragY = e.getY();
					lastDragTime = now;
					vp.panPixels(dx, dy);
					vp.clampCentre(world, 64);
				}
			}
			e.consume();
			return e;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent e)
		{
			// not consumed: the game has to keep seeing where the mouse is, or RuneLite's sidebar caret (drawn from the
			// game's last mouse position) stays stuck at the world map icon
			synchronized (GoldmanMapView.this)
			{
				mouseX = e.getX();
				mouseY = e.getY();
			}
			return e;
		}

		@Override
		public MouseEvent mouseExited(MouseEvent e)
		{
			synchronized (GoldmanMapView.this)
			{
				mouseX = mouseY = -1;
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			e.consume();
			return e;
		}
	};

	final MouseWheelListener wheel = e ->
	{
		synchronized (GoldmanMapView.this)
		{
			flying = false;
			// from the target, so quick scrolling keeps adding up while the view eases toward it
			// a fast flick can report several notches in one event: cap it so one event never jumps far
			double rot = Math.max(-3, Math.min(3, e.getPreciseWheelRotation()));
			zoomAt(e.getX(), e.getY(), Math.max(targetScale, 1e-6) * Math.exp(-rot * ZOOM_PER_NOTCH));
		}
		e.consume();
		return e;
	};

	final KeyListener keys = new KeyListener()
	{
		@Override
		public void keyTyped(KeyEvent e)
		{
			e.consume();
		}

		@Override
		public void keyPressed(KeyEvent e)
		{
			// the map swallows every key so nothing reaches the game; only Esc does anything (it closes the map)
			e.consume();
			if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				onClose.run();
			}
		}

		@Override
		public void keyReleased(KeyEvent e)
		{
			e.consume();
		}
	};

	// ------------------------------------------------------------------ navigation

	private double minScale()
	{
		return Math.max(0.02, vp.fitScale(world, 24) * 0.9);
	}

	private double clampScale(double s)
	{
		return Math.max(minScale(), Math.min(MAX_SCALE, s));
	}

	/** ease toward a new zoom, keeping the world point under screen point (sx, sy) still */
	private void zoomAt(double sx, double sy, double scale)
	{
		flying = false;
		targetScale = clampScale(scale);
		anchorSx = sx;
		anchorSy = sy;
		anchorWx = vp.wx(sx);
		anchorWy = vp.wy(sy);
	}

	synchronized void showWholeMap(boolean animate)
	{
		double s = vp.fitScale(world, 24);
		flyTo((world[0] + world[2]) / 2, (world[1] + world[3]) / 2, s, animate);
	}

	synchronized void showPlayer(boolean animate)
	{
		WorldPoint p = host.player();
		if (p == null)
		{
			return;
		}
		flyTo(p.getX() + 0.5, p.getY() + 0.5, Math.max(targetScale, 6), animate);
	}

	/** jump to a view (also used by tests) */
	synchronized void setView(double x, double y, double scale)
	{
		flyTo(x, y, scale, false);
		initialised = true;
	}

	synchronized void setMouse(int x, int y)
	{
		mouseX = x;
		mouseY = y;
	}

	private void flyTo(double x, double y, double scale, boolean animate)
	{
		scale = clampScale(scale);
		if (!animate)
		{
			vp.cx = x;
			vp.cy = y;
			vp.scale = scale;
			targetScale = scale;
			flying = false;
			return;
		}
		flying = true;
		flyStart = System.nanoTime();
		flyFromX = vp.cx;
		flyFromY = vp.cy;
		flyFromScale = vp.scale;
		flyToX = x;
		flyToY = y;
		flyToScale = scale;
		targetScale = scale;
	}

	// ------------------------------------------------------------------ animation (once per drawn frame)

	private void step()
	{
		long now = System.nanoTime();
		double dt = Math.min(50, (now - lastFrame) / 1e6);
		lastFrame = now;
		if (flying)
		{
			double t = Math.min(1, (now - flyStart) / 1e6 / 450.0);
			double e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; // ease in-out
			vp.cx = flyFromX + (flyToX - flyFromX) * e;
			vp.cy = flyFromY + (flyToY - flyFromY) * e;
			vp.scale = flyFromScale * Math.pow(flyToScale / flyFromScale, e);
			if (t >= 1)
			{
				flying = false;
				vp.scale = flyToScale;
			}
		}
		else
		{
			if (Math.abs(Math.log(targetScale / vp.scale)) > 0.0008)
			{
				double k = 1 - Math.exp(-dt / 85.0);
				vp.zoomKeeping(anchorWx, anchorWy, anchorSx, anchorSy, vp.scale * Math.pow(targetScale / vp.scale, k));
			}
			else if (vp.scale != targetScale)
			{
				vp.zoomKeeping(anchorWx, anchorWy, anchorSx, anchorSy, targetScale);
			}
		}
		vp.clampCentre(world, 64);
	}

	// ------------------------------------------------------------------ painting

	synchronized void render(Graphics2D g0, int w, int h)
	{
		Graphics2D g = (Graphics2D) g0.create();
		try
		{
			vp.w = Math.max(1, w);
			vp.h = Math.max(1, h);
			if (!initialised)
			{
				// the first time the map opens after logging in it shows the whole world
				showWholeMap(false);
				initialised = true;
			}
			step();
			long nowNs = System.nanoTime();
			double fadeDt = Math.min(100, (nowNs - alphaNs) / 1e6);
			alphaNs = nowNs;
			alpha = Math.max(0, Math.min(1, alpha + (open ? fadeDt : -fadeDt) / FADE_MS));
			if (alpha <= 0)
			{
				if (memoryHeld && !open)
				{
					memoryHeld = false;
					tiles.releaseMemory(); // the fade-out is over: let go of the pictures
				}
				return;
			}
			if (alpha < 1)
			{
				g.setComposite(java.awt.AlphaComposite.SrcOver.derive((float) (alpha * alpha * (3 - 2 * alpha))));
			}
			g.setClip(0, 0, vp.w, vp.h);
			g.setColor(OCEAN);
			g.fillRect(0, 0, vp.w, vp.h);
			double dpr = g.getDeviceConfiguration().getDefaultTransform().getScaleX();
			if (dpr <= 0)
			{
				dpr = 1;
			}
			drawTiles(g, dpr);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			GoldmanArea hover = hoverArea();
			if (confirming != null && !dragging && hover != confirming)
			{
				confirming = null; // moved off the area: the confirmation lapses
			}
			drawAreas(g, hover);
			drawHud(g, hover);
		}
		finally
		{
			g.dispose();
		}
	}

	private void drawTiles(Graphics2D g, double dpr)
	{
		int z = MapTiles.levelFor(vp.scale * dpr);
		int span = MapTiles.span(z);
		int tx0 = Math.floorDiv((int) Math.floor(vp.wx(0)), span), tx1 = Math.floorDiv((int) Math.floor(vp.wx(vp.w)), span);
		int ty0 = Math.floorDiv((int) Math.floor(vp.wy(vp.h)), span), ty1 = Math.floorDiv((int) Math.floor(vp.wy(0)), span);
		double ccx = vp.cx / span, ccy = vp.cy / span;
		List<int[]> need = new ArrayList<>();
		for (int tx = tx0; tx <= tx1; tx++)
		{
			for (int ty = ty0; ty <= ty1; ty++)
			{
				if (regions.hasTile(z, tx, ty))
				{
					need.add(new int[]{tx, ty});
				}
			}
		}
		if (need.size() > 4000)
		{
			return;
		}
		// middle of the screen first
		need.sort((a, b) -> Double.compare(Math.hypot(a[0] + 0.5 - ccx, a[1] + 0.5 - ccy), Math.hypot(b[0] + 0.5 - ccx, b[1] + 0.5 - ccy)));
		// the biggest zoom-out pictures also show dungeons beyond the surface world: only draw inside it
		java.awt.Shape oldClip = g.getClip();
		// round inward: a clip that sticks out a fraction of a pixel lets a sliver of the dungeon / blank picture beyond the
		// world edge show up as a thin white line
		int cx0 = (int) Math.ceil(vp.sx(world[0])), cx1 = (int) Math.floor(vp.sx(world[2]));
		int cy0 = (int) Math.ceil(vp.sy(world[3])), cy1 = (int) Math.floor(vp.sy(world[1]));
		g.clipRect(cx0, cy0, cx1 - cx0, cy1 - cy0);
		boolean upscaling = vp.scale * dpr > Math.pow(2, z) * 1.0001; // more screen pixels than picture pixels
		Object interp = upscaling ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR
			: RenderingHints.VALUE_INTERPOLATION_BILINEAR;
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interp);
		for (int[] t : need)
		{
			int dx0 = (int) Math.round(vp.sx((double) t[0] * span));
			int dx1 = (int) Math.round(vp.sx((double) (t[0] + 1) * span));
			int dy0 = (int) Math.round(vp.sy((double) (t[1] + 1) * span));
			int dy1 = (int) Math.round(vp.sy((double) t[1] * span));
			BufferedImage img = tiles.want(z, t[0], t[1]);
			if (img != null)
			{
				g.drawImage(img, dx0, dy0, dx1, dy1, 0, 0, MapTiles.SIZE, MapTiles.SIZE, null);
			}
			else if (tiles.exists(z, t[0], t[1]))
			{
				fallback(g, z, t[0], t[1], dx0, dy0, dx1, dy1);
			}
		}
		g.setClip(oldClip);
		tiles.endFrame();
	}

	/** While a square loads, show the same ground from a coarser (or finer) zoom level so nothing blinks out. */
	private void fallback(Graphics2D g, int z, int tx, int ty, int dx0, int dy0, int dx1, int dy1)
	{
		for (int dz = 1; dz <= 5 && z - dz >= MapTiles.MIN_Z; dz++)
		{
			BufferedImage p = tiles.peek(z - dz, tx >> dz, ty >> dz);
			if (p != null)
			{
				int mask = (1 << dz) - 1;
				int sub = MapTiles.SIZE >> dz;
				int sx = (tx & mask) * sub;
				int sy = (mask - (ty & mask)) * sub; // y runs north, picture rows run south
				g.drawImage(p, dx0, dy0, dx1, dy1, sx, sy, sx + sub, sy + sub, null);
				return;
			}
		}
		if (z + 1 <= MapTiles.MAX_Z)
		{
			int mx = (dx0 + dx1) / 2, my = (dy0 + dy1) / 2;
			for (int i = 0; i < 2; i++)
			{
				for (int j = 0; j < 2; j++)
				{
					BufferedImage c = tiles.peek(z + 1, tx * 2 + i, ty * 2 + j);
					if (c != null)
					{
						int cx0 = i == 0 ? dx0 : mx, cx1 = i == 0 ? mx : dx1;
						int cy0 = j == 1 ? dy0 : my, cy1 = j == 1 ? my : dy1; // j=1 is the northern half: top
						g.drawImage(c, cx0, cy0, cx1, cy1, 0, 0, MapTiles.SIZE, MapTiles.SIZE, null);
					}
				}
			}
		}
	}

	private Path2D[] pathsOf(GoldmanArea a)
	{
		return paths.computeIfAbsent(a, k ->
		{
			List<Path2D> out = new ArrayList<>();
			for (List<double[][]> part : k.getParts())
			{
				Path2D p = new Path2D.Double(Path2D.WIND_EVEN_ODD);
				for (double[][] ring : part)
				{
					for (int i = 0; i < ring.length; i++)
					{
						if (i == 0)
						{
							p.moveTo(ring[i][0], ring[i][1]);
						}
						else
						{
							p.lineTo(ring[i][0], ring[i][1]);
						}
					}
					p.closePath();
				}
				out.add(p);
			}
			return out.toArray(new Path2D[0]);
		});
	}

	private boolean affordable(GoldmanArea a)
	{
		return !host.isUnlocked(a) && host.balance() >= host.cost(a);
	}

	/**
	 * A click-and-release (not a drag) on the map. The first click on a locked area you can afford arms its "Confirm
	 * unlock" tooltip; a second click on the same area buys it (returned). Anything else just clears the confirmation.
	 */
	private GoldmanArea clicked(int x, int y)
	{
		GoldmanArea a = host.areas().areaAt((int) Math.floor(vp.wx(x)), (int) Math.floor(vp.wy(y)));
		if (a == null || !affordable(a))
		{
			confirming = null;
			return null;
		}
		if (confirming == a)
		{
			confirming = null;
			return a;
		}
		confirming = a;
		return null;
	}

	private GoldmanArea hoverArea()
	{
		if (mouseX < 0 || dragging)
		{
			return null;
		}
		int x = (int) Math.floor(vp.wx(mouseX)), y = (int) Math.floor(vp.wy(mouseY));
		return host.areas().areaAt(x, y);
	}

	private void drawAreas(Graphics2D g, GoldmanArea hover)
	{
		AffineTransform at = new AffineTransform();
		at.translate(vp.w / 2.0 - vp.cx * vp.scale, vp.h / 2.0 + vp.cy * vp.scale);
		at.scale(vp.scale, -vp.scale);
		double left = vp.wx(0), right = vp.wx(vp.w), top = vp.wy(0), bottom = vp.wy(vp.h);
		// lines get thinner as you zoom out (full thickness from about 4 pixels per tile up)
		double thin = Math.max(0.22, Math.min(1.0, Math.sqrt(vp.scale / 4)));
		BasicStroke lockedStroke = new BasicStroke((float) Math.max(0.6, 2.25 * thin), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		BasicStroke unlockedStroke = new BasicStroke((float) Math.max(0.5, 1.5 * thin), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		BasicStroke hoverStroke = new BasicStroke((float) Math.max(1.4, 3.0 * thin), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		// three passes, so a red border always sits above a green one where they meet:
		// the red fill of locked areas, then the green outlines of unlocked areas, then the red outlines
		List<GoldmanArea> lockedInView = new ArrayList<>();
		List<GoldmanArea> unlockedInView = new ArrayList<>();
		for (GoldmanArea a : host.areas().getAreas())
		{
			if (a == hover || a.getMaxX() < left || a.getMinX() > right || a.getMaxY() < bottom || a.getMinY() > top)
			{
				continue;
			}
			(host.isUnlocked(a) ? unlockedInView : lockedInView).add(a);
		}
		g.setColor(LOCKED_FILL);
		for (GoldmanArea a : lockedInView)
		{
			for (Path2D p : pathsOf(a))
			{
				g.fill(at.createTransformedShape(p));
			}
		}
		g.setStroke(unlockedStroke);
		g.setColor(UNLOCKED_LINE);
		for (GoldmanArea a : unlockedInView)
		{
			for (Path2D p : pathsOf(a))
			{
				g.draw(at.createTransformedShape(p));
			}
		}
		g.setStroke(lockedStroke);
		g.setColor(LOCKED_LINE);
		for (GoldmanArea a : lockedInView)
		{
			for (Path2D p : pathsOf(a))
			{
				g.draw(at.createTransformedShape(p));
			}
		}
		// the hovered area last, so its white outline sits on top of every neighbour's line
		if (hover != null)
		{
			boolean unlocked = host.isUnlocked(hover);
			for (Path2D p : pathsOf(hover))
			{
				Shape s = at.createTransformedShape(p);
				g.setColor(unlocked ? UNLOCKED_FILL_HOVER : LOCKED_FILL_HOVER);
				g.fill(s);
				g.setStroke(hoverStroke);
				g.setColor(HOVER_LINE);
				g.draw(s);
			}
		}
	}

	private void drawBox(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(PANEL);
		g.fillRect(x, y, w, h);
		g.setStroke(new BasicStroke(1.5f));
		g.setColor(BORDER);
		g.draw(new java.awt.geom.Rectangle2D.Double(x + 0.75, y + 0.75, w - 1.5, h - 1.5));
	}

	private void drawHud(Graphics2D g, GoldmanArea hover)
	{
		// bottom right: map download status
		String status = null;
		if (tiles.offline())
		{
			status = "Can't reach the map server - showing saved pictures only";
		}
		if (status != null)
		{
			int sw = FONT.width(status) + 16, sh = FONT.lineHeight() + 12;
			int sx = vp.w - 12 - sw, sy = vp.h - 12 - sh;
			drawBox(g, sx, sy, sw, sh);
			FONT.draw(g, status, sx + 8, sy + 6, tiles.offline() ? RED : Color.WHITE);
		}

		if (hover != null)
		{
			drawTooltip(g, hover);
		}
	}

	/** "Unlock <area> (<cost> gp)": Unlock white, the area yellow, the price green if you can afford it and red if not. */
	private void drawTooltip(Graphics2D g, GoldmanArea a)
	{
		String[] parts;
		Color[] cols;
		if (host.isUnlocked(a))
		{
			parts = new String[]{a.getName()};
			cols = new Color[]{YELLOW};
		}
		else
		{
			long c = host.cost(a);
			boolean confirm = confirming == a && host.balance() >= c;
			parts = new String[]{confirm ? "Confirm unlock " : "Unlock ", a.getName(), String.format(Locale.ROOT, " (%,d gp)", c)};
			cols = new Color[]{Color.WHITE, YELLOW, host.balance() >= c ? GREEN : TIP_RED};
		}
		int tw = 0;
		for (String p : parts)
		{
			tw += FONT.width(p);
		}
		int w = tw + 8, h = FONT.lineHeight() + 10;
		// a bit below and a bit to the left of the mouse
		int x = mouseX - 4, y = mouseY + 22;
		if (y + h > vp.h - 8)
		{
			y = mouseY - 10 - h;
		}
		x = Math.max(8, Math.min(x, vp.w - 8 - w));
		y = Math.max(8, y);
		drawBox(g, x, y, w, h);
		// a black drop shadow one pixel to the south east, then the text itself
		for (int pass = 0; pass < 2; pass++)
		{
			int tx = x + 4;
			for (int i = 0; i < parts.length; i++)
			{
				FONT.draw(g, parts[i], tx + (1 - pass), y + 5 + (1 - pass), pass == 0 ? Color.BLACK : cols[i]);
				tx += FONT.width(parts[i]);
			}
		}
	}
}

package com.goldmanmode;

import java.awt.Canvas;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

/** Opens and closes the Goldman world map and wires it up to the game. The map itself is {@link GoldmanMapView}. */
@Singleton
class GoldmanMapWindow
{
	private static final String MENU_OPTION = "Open";
	/** orange, like the other interface names in the menu */
	private static final String MENU_TARGET = "<col=ff9040>Goldman Map</col>";

	private final Client client;
	private final ClientThread clientThread;
	private final MouseManager mouseManager;
	private final KeyManager keyManager;
	private final OkHttpClient okHttpClient;
	private final ScheduledExecutorService executor;
	private final GoldmanState state;
	private final GoldmanModeConfig config;
	private final GoldmanMapOverlay overlay;

	private volatile WorldPoint playerPos;
	private Filepath dataDir;
	private MapTiles mapTiles;
	private GoldmanMapView mapView;

	@Inject
	GoldmanMapWindow(Client client, ClientThread clientThread, MouseManager mouseManager, KeyManager keyManager,
		OkHttpClient okHttpClient, ScheduledExecutorService executor, GoldmanState state, GoldmanModeConfig config, GoldmanMapOverlay overlay)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.mouseManager = mouseManager;
		this.keyManager = keyManager;
		this.okHttpClient = okHttpClient;
		this.executor = executor;
		this.state = state;
		this.config = config;
		this.overlay = overlay;
	}

	/** Adds "Open Goldman Map" to the world map icon's right-click menu. */
	void onMenuEntryAdded(MenuEntryAdded e)
	{
		if (!isWorldMapEntry(e.getMenuEntry()))
		{
			return;
		}
		for (MenuEntry m : client.getMenu().getMenuEntries())
		{
			if (MENU_TARGET.equals(m.getTarget()))
			{
				return;
			}
		}
		client.getMenu().createMenuEntry(-1).setOption(MENU_OPTION).setTarget(MENU_TARGET).setType(MenuAction.RUNELITE).onClick(m -> openLater());
	}

	/** With "Default to Goldman Map" on, a plain left click on the world map icon opens the Goldman map instead. */
	void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (config.defaultToGoldmanMap() && !client.isMenuOpen() && isWorldMapEntry(e.getMenuEntry()))
		{
			e.consume();
			openLater();
		}
	}

	/** One of the world map icon's own menu entries ("Floating World Map" and so on), not ours. */
	private static boolean isWorldMapEntry(MenuEntry entry)
	{
		boolean icon = entry.getParam1() == InterfaceID.Orbs.ORB_WORLDMAP || entry.getParam1() == InterfaceID.Orbs.WORLDMAP;
		return icon && Text.removeTags(entry.getOption() + " " + entry.getTarget()).toLowerCase(Locale.ROOT).contains("world map");
	}

	/** The plugin's data folder, where the map pictures are cached. */
	void setDataDirectory(Filepath dir)
	{
		dataDir = dir;
	}

	/** The player's tile for the "you are here" marker, or null when not in the surface world. */
	void setPlayer(WorldPoint tile)
	{
		playerPos = tile;
	}

	boolean isOpen()
	{
		GoldmanMapView v = mapView;
		return v != null && v.isOpen();
	}

	void openLater()
	{
		SwingUtilities.invokeLater(this::open);
	}

	void closeLater()
	{
		SwingUtilities.invokeLater(this::close);
	}

	/** Forget where the map was looking, so the next login starts on the whole map again. */
	void resetView()
	{
		if (mapView != null)
		{
			mapView.resetView();
		}
	}

	void shutDown()
	{
		SwingUtilities.invokeLater(() ->
		{
			close();
			if (mapTiles != null)
			{
				mapTiles.shutdown();
				mapTiles = null;
			}
			mapView = null;
			overlay.setView(null);
		});
	}

	/** AWT thread. */
	private void open()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (mapView == null)
		{
			MapRegions regions = MapRegions.load();
			mapTiles = new MapTiles(okHttpClient, dataDir.joinSegment("maptiles"),
				regions, () ->
				{
				}, executor);
			mapView = new GoldmanMapView(host, mapTiles, regions, this::close);
			overlay.setView(mapView);
		}
		if (mapView.isOpen())
		{
			return;
		}
		mapView.open();
		// Not first in line: Stretched Mode's translator is registered first and rescales the mouse position to the
		// game's own pixels for whoever comes after it, and that is the position the map is drawn in.
		mouseManager.registerMouseListener(mapView.mouse);
		mouseManager.registerMouseWheelListener(mapView.wheel);
		keyManager.registerKeyListener(mapView.keys);
		Canvas canvas = client.getCanvas();
		if (canvas != null)
		{
			canvas.requestFocusInWindow(); // the sidebar button had the keyboard: the map needs it to hear keys
		}
	}

	/** AWT thread. The view releases its pictures itself once it has finished fading out. */
	private void close()
	{
		GoldmanMapView v = mapView;
		if (v == null || !v.isOpen())
		{
			return;
		}
		v.close();
		mouseManager.unregisterMouseListener(v.mouse);
		mouseManager.unregisterMouseWheelListener(v.wheel);
		keyManager.unregisterKeyListener(v.keys);
	}

	private final GoldmanMapView.Host host = new GoldmanMapView.Host()
	{
		@Override
		public AreaIndex areas()
		{
			return state.getIndex();
		}

		@Override
		public boolean isUnlocked(GoldmanArea a)
		{
			return state.isUnlocked(a);
		}

		@Override
		public boolean isFree(GoldmanArea a)
		{
			return state.isFree(a);
		}

		@Override
		public long cost(GoldmanArea a)
		{
			return state.costOf(a);
		}

		@Override
		public long balance()
		{
			return state.getBalance();
		}

		@Override
		public WorldPoint player()
		{
			return playerPos;
		}

		@Override
		public void buy(GoldmanArea a)
		{
			String err = state.buy(a);
			String msg = err == null
				? "<col=ffffff>Goldman Mode:</col> <col=00ff00>" + a.getName() + " has been unlocked.</col>"
				: "Goldman Mode: " + err + ".";
			clientThread.invoke(() ->
			{
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
				}
			});
		}
	};
}

package com.goldmanmode;

import java.awt.AlphaComposite;
