/** Shows locked areas on the minimap: a tint inside and a line along the same borders the in-game barrier follows. */
@Singleton
public class GoldmanMinimapOverlay extends Overlay
{
	private final Client client;
	private final GoldmanState state;

	/** scratch image the tint is drawn into, so areas that overlap are tinted once, not twice */
	private BufferedImage layer;
	private final double[] tmp = new double[2];

	@Inject
	GoldmanMinimapOverlay(Client client, GoldmanState state)
	{
		this.client = client;
		this.state = state;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	private Widget minimapWidget()
	{
		Widget w;
		if (client.isResized())
		{
			w = client.getVarbitValue(4607) == 1
				? client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP)
				: client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		else
		{
			w = client.getWidget(InterfaceID.Toplevel.MINIMAP);
		}
		return w == null || w.isHidden() ? null : w;
	}


	/** buttons that sit on top of the minimap (the world map globe, the wiki banner, the compass, the orbs) */
	private static final int[] ROUND_WIDGETS = {
		InterfaceID.Orbs.ORB_WORLDMAP, InterfaceID.Orbs.WORLDMAP, InterfaceID.Orbs.ORB_HEALTH, InterfaceID.Orbs.ORB_PRAYER,
		InterfaceID.Orbs.ORB_RUNENERGY, InterfaceID.Orbs.ORB_SPECENERGY, InterfaceID.Orbs.ORB_STORE, InterfaceID.Orbs.XP_DROPS,
		InterfaceID.Orbs.CR_BUTTON, InterfaceID.Toplevel.COMPASSCLICK, InterfaceID.ToplevelOsrsStretch.COMPASSCLICK,
		InterfaceID.ToplevelPreEoc.COMPASSCLICK, InterfaceID.ToplevelOsm.COMPASSCLICK
	};
	private static final int[] BOX_WIDGETS = {InterfaceID.Orbs.WIKI};

	/** takes the other buttons out of the area we may draw in, so the tint never covers them */
	private void cutOut(Area clip)
	{
		for (int id : ROUND_WIDGETS)
		{
			Rectangle b = visibleBounds(id, 80);
			if (b != null)
			{
				clip.subtract(new Area(new Ellipse2D.Double(b.x, b.y, b.width, b.height)));
			}
		}
		for (int id : BOX_WIDGETS)
		{
			Rectangle b = visibleBounds(id, 120);
			if (b != null)
			{
				clip.subtract(new Area(b));
			}
		}
	}

	private Rectangle visibleBounds(int id, int maxSize)
	{
		Widget wd = client.getWidget(id);
		if (wd == null || wd.isHidden() || wd.isSelfHidden())
		{
			return null;
		}
		Rectangle b = wd.getBounds();
		// a container much bigger than a button is not the button: leave it alone
		return b == null || b.width <= 0 || b.height <= 0 || b.width > maxSize || b.height > maxSize ? null : b;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (Instances.isInstanced(client))
		{
			return null;
		}
		Widget mm = minimapWidget();
		WorldView wv = client.getTopLevelWorldView();
		CameraFocusableEntity focusEntity = client.getCameraFocusEntity();
		if (mm == null || wv == null || focusEntity == null)
		{
			return null;
		}
		LocalPoint focus = focusEntity.getCameraFocus();
		Point loc = mm.getCanvasLocation();
		if (focus == null || focus.getWorldView() != 0 || loc == null)
		{
			return null;
		}
		final int w = mm.getWidth(), h = mm.getHeight();
		if (w <= 0 || h <= 0)
		{
			return null;
		}
		final double zoom = client.getMinimapZoom();
		if (zoom <= 0)
		{
			return null;
		}
		AreaIndex index = state.getIndex();
		List<GoldmanArea> areas = index.getAreas();
		if (areas.isEmpty())
		{
			return null;
		}

		// where the player is, in world tiles, and the minimap's centre on the canvas
		final double px = wv.getBaseX() + focus.getX() / (double) Perspective.LOCAL_TILE_SIZE;
		final double py = wv.getBaseY() + focus.getY() / (double) Perspective.LOCAL_TILE_SIZE;
		final double cx = loc.getX() + w / 2.0, cy = loc.getY() + h / 2.0;
		final int yaw = client.getCameraYawTarget();
		final double reach = Math.max(w, h) / 2.0 / zoom + 3; // tiles from the player to the edge of the minimap

		Shape oldClip = g.getClip();
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		double rad = Math.min(w, h) / 2.0; // the visible minimap is exactly the circle inscribed in its draw area
		Area clip = new Area(new Ellipse2D.Double(cx - rad, cy - rad, rad * 2, rad * 2));
		cutOut(clip);
		g.setClip(clip);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// ---- tint
		Color tint = Settings.MINIMAP_TINT_COLOUR;
		if (tint.getAlpha() > 0)
		{
			if (layer == null || layer.getWidth() != w || layer.getHeight() != h)
			{
				layer = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			}
			Graphics2D lg = layer.createGraphics();
			lg.setComposite(AlphaComposite.Clear);
			lg.fillRect(0, 0, w, h);
			lg.setComposite(AlphaComposite.Src);
			lg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			lg.setColor(new Color(tint.getRed(), tint.getGreen(), tint.getBlue(), 255));
			boolean any = false;
			for (int i = 0; i < areas.size(); i++)
			{
				if (!state.isLockedIdx(i))
				{
					continue;
				}
				GoldmanArea a = areas.get(i);
				if (a.getMaxX() + 1 < px - reach || a.getMinX() > px + reach || a.getMaxY() + 1 < py - reach || a.getMinY() > py + reach)
				{
					continue;
				}
				Path2D.Double path = new Path2D.Double(Path2D.WIND_EVEN_ODD);
				for (double[][] ring : a.getRings())
				{
					for (int k = 0; k < ring.length; k++)
					{
						MinimapMath.project(ring[k][0] - px, ring[k][1] - py, zoom, yaw, tmp);
						double sx = cx + tmp[0] - loc.getX(), sy = cy + tmp[1] - loc.getY();
						if (k == 0)
						{
							path.moveTo(sx, sy);
						}
						else
						{
							path.lineTo(sx, sy);
						}
					}
					path.closePath();
				}
				lg.fill(path);
				any = true;
			}
			lg.dispose();
			if (any)
			{
				java.awt.Composite oldComp = g.getComposite();
				g.setComposite(AlphaComposite.SrcOver.derive(tint.getAlpha() / 255f));
				g.drawImage(layer, loc.getX(), loc.getY(), null);
				g.setComposite(oldComp);
			}
		}

		// ---- border lines: where exactly one side is locked, on the outline of the locked area
		Color lineColour = Settings.MINIMAP_BORDER_COLOUR;
		if (lineColour.getAlpha() > 0)
		{
			BarrierGeometry geo = index.getBarrier();
			g.setColor(lineColour);
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			Line2D.Double line = new Line2D.Double();
			for (int rx = (int) Math.floor(px - reach) >> 6; rx <= (int) Math.floor(px + reach) >> 6; rx++)
			{
				for (int ry = (int) Math.floor(py - reach) >> 6; ry <= (int) Math.floor(py + reach) >> 6; ry++)
				{
					List<BarrierGeometry.Piece> pieces = geo.region(rx, ry);
					if (pieces == null)
					{
						continue;
					}
					for (BarrierGeometry.Piece pc : pieces)
					{
						if (!state.isLockedBorder(pc))
						{
							continue;
						}
						MinimapMath.project(pc.x1 - px, pc.y1 - py, zoom, yaw, tmp);
						double ax = cx + tmp[0], ay = cy + tmp[1];
						MinimapMath.project(pc.x2 - px, pc.y2 - py, zoom, yaw, tmp);
						line.setLine(ax, ay, cx + tmp[0], cy + tmp[1]);
						g.draw(line);
					}
				}
			}
		}

		g.setClip(oldClip);
		if (aa != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		}
		return null;
	}
}

package com.goldmanmode;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * The plugin's settings menu: miscellaneous behavior, the area cost multiplier and the payout multipliers. Everything else is
 * fixed (see {@link Settings}). This group is also where the plugin keeps your Goldman GP balance and unlocked areas.
 * <p>
 * Each multiplier is a number box that starts at 1.0 and moves by 0.1 with its up and down arrows (you can also type
 * a value). 1.0 pays or costs exactly the normal amount, 2.0 doubles it, 0.5 halves it, 0 turns it off.
 */
@ConfigGroup(GoldmanModeConfig.GROUP)
public interface GoldmanModeConfig extends Config
{
	String GROUP = "goldmanmode";

	@ConfigSection(name = "Behavior", description = "Controls various miscellaneous behaviors of the plugin", position = 0)
	String BEHAVIOR = "behavior";

	@ConfigSection(name = "Cost multiplier", description = "Makes areas cost more or less than base 1.0 factor", position = 1)
	String COST_MULTIPLIER = "costMultiplier";

	@ConfigSection(name = "Payout multipliers", description = "Makes payouts give more or less than the base 1.0 factor", position = 2)
	String PAYOUT_MULTIPLIERS = "payoutMultipliers";

	@ConfigItem(keyName = "blockLockedClicks", name = "Block clicks in locked areas", description = "Walking to, and clicking NPCs, objects, items, and players in locked areas does nothing", section = BEHAVIOR, position = 0)
	default boolean blockLockedClicks()
	{
		return true;
	}

	@ConfigItem(keyName = "defaultToGoldmanMap", name = "Default to Goldman Map", description = "Makes left-clicking the world map show the Goldman Map", section = BEHAVIOR, position = 1)
	default boolean defaultToGoldmanMap()
	{
		return true;
	}

	@ConfigItem(keyName = "showGpOverlay", name = "Show Goldman GP overlay", description = "Shows the auto-updating Goldman GP overlay on the screen", section = BEHAVIOR, position = 2)
	default boolean showGpOverlay()
	{
		return true;
	}

	@ConfigItem(keyName = "areaCostMultiplier", name = "Area costs", description = "Multiplies how much areas cost, by factors of 0.1 (eg. 2.0 doubles costs while 0.5 halves costs)", section = COST_MULTIPLIER, position = 0)
	default double areaCostMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "xpMultiplier", name = "Experience", description = "Multiplies how much experience pays out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 0)
	default double xpMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "killsMultiplier", name = "Kills", description = "Multiplies how much kills pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 1)
	default double killsMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "skillLevelsMultiplier", name = "Skill levels", description = "Multiplies how much skill levels pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 2)
	default double skillLevelsMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "combatLevelsMultiplier", name = "Combat levels", description = "Multiplies how much combat levels pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 3)
	default double combatLevelsMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "questsMultiplier", name = "Quests", description = "Multiplies how much quests pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 4)
	default double questsMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "diariesMultiplier", name = "Achievement Diaries", description = "Multiplies how much Achievement Diaries pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 5)
	default double diariesMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "combatAchievementsMultiplier", name = "Combat Achievements", description = "Multiplies how much Combat Achievements pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 6)
	default double combatAchievementsMultiplier()
	{
		return 1.0;
	}

	@ConfigItem(keyName = "collectionLogMultiplier", name = "Collection logs", description = "Multiplies how much collection logs pay out, by factors of 0.1 (eg. 2.0 doubles payouts while 0.5 halves payouts)", section = PAYOUT_MULTIPLIERS, position = 7)
	default double collectionLogMultiplier()
	{
		return 1.0;
	}
}

package com.goldmanmode;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.EnumMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Goldman Mode",
	internalName = "goldman-mode",
	description = "Unlock Gielinor one area at a time by earning and spending Goldman GP!",
	tags = {"ironman", "goldman", "unlock", "areas", "challenge", "restricted"}
)
public class GoldmanModePlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private GoldmanState state;
	@Inject
	private GoldmanPanel panel;
	@Inject
	private GoldmanBarrierOverlay sceneOverlay;
	@Inject
	private GoldmanGpOverlay gpOverlay;
	@Inject
	private GoldmanMinimapOverlay minimapOverlay;
	@Inject
	private GoldmanMapOverlay mapOverlay;
	@Inject
	private GoldmanMapWindow mapWindow;
	@Inject
	private GoldmanClickBlocker clickBlocker;
	@Inject
	private GoldmanAchievements achievements;
	@Inject
	private ClogTooltip clogTooltip;

	private NavigationButton navButton;

	@Provides
	GoldmanModeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GoldmanModeConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		Filepath dataDir = getPluginDirectory();
		mapWindow.setDataDirectory(dataDir);
		state.load(dataDir);
		BufferedImage icon = ImageUtil.loadImageResource(GoldmanModePlugin.class, "icon_16.png");
		navButton = NavigationButton.builder()
			.tooltip("Goldman Mode")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(sceneOverlay);
		overlayManager.add(minimapOverlay);
		overlayManager.add(gpOverlay);
		overlayManager.add(mapOverlay);
		clickBlocker.startUp();
		log.info("Goldman Mode started with {} areas ({})", state.getIndex().getAreas().size(), state.getSource());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(gpOverlay);
		overlayManager.remove(mapOverlay);
		state.flush();
		clickBlocker.shutDown();
		mapWindow.shutDown();
		clientToolbar.removeNavigation(navButton);
		panel.shutDown();
		state.setCurrent(null);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (GoldmanModeConfig.GROUP.equals(e.getGroup()))
		{
			state.configChanged();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged e)
	{
		state.configChanged();
	}

	// ------------------------------------------------------------------ earning GP from experience

	/** the xp each skill had last time we looked; xp gained after that is paid out */
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	/** the real level of each skill and the combat level they add up to, for the level-up bonuses */
	private final Map<Skill, Integer> lastLevel = new EnumMap<>(Skill.class);
	private int lastCombat;
	private boolean xpBaselined;

	/** Takes the starting xp of every skill once per login, so the login burst of stats is never paid. */
	private void baselineXp()
	{
		if (xpBaselined || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		lastXp.clear();
		for (Skill s : Skill.values())
		{
			if (!isOverall(s))
			{
				lastXp.put(s, client.getSkillExperience(s));
				lastLevel.put(s, client.getRealSkillLevel(s));
			}
		}
		lastCombat = combatLevel();
		xpBaselined = true;
	}

	/** the game's "all skills" total, which is not a skill we track (Skill.OVERALL is marked deprecated, but still the only way to name it) */
	@SuppressWarnings("deprecation")
	private static boolean isOverall(Skill s)
	{
		return s == Skill.OVERALL;
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (!xpBaselined || isOverall(e.getSkill()))
		{
			return;
		}
		Integer prev = lastXp.put(e.getSkill(), e.getXp());
		if (prev != null && e.getXp() > prev)
		{
			long xpGp = state.earnFromXp((long) e.getXp() - prev, Settings.XP_PER_GP);
			// SPAM is the game's "filtered" message type: it only shows when the Game tab is set to All
			announce(ChatMessageType.SPAM, xpGp, e.getSkill().getName() + " xp");
		}

		// level-up bonuses: every skill level gained, and every combat level that follows from it
		Integer prevLevel = lastLevel.put(e.getSkill(), e.getLevel());
		if (prevLevel != null && e.getLevel() > prevLevel)
		{
			long levelGp = state.scaled(GoldmanState.Payout.SKILL_LEVELS, LevelBonuses.forSkillLevels(prevLevel, e.getLevel()));
			if (levelGp > 0)
			{
				state.addBalance(levelGp);
				announce(ChatMessageType.GAMEMESSAGE, levelGp, e.getSkill().getName() + " level " + e.getLevel());
			}
		}
		int combat = combatLevel();
		if (combat > lastCombat)
		{
			long combatGp = state.scaled(GoldmanState.Payout.COMBAT_LEVELS, LevelBonuses.forCombatLevels(lastCombat, combat));
			if (combatGp > 0)
			{
				state.addBalance(combatGp);
				announce(ChatMessageType.GAMEMESSAGE, combatGp, "combat level " + combat);
			}
		}
		lastCombat = combat;
	}

	/** NPCs you have hit; one that dies while it is in here pays out */
	private final Set<NPC> hitByMe = Collections.newSetFromMap(new IdentityHashMap<>());

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getHitsplat().isMine() && e.getActor() instanceof NPC)
		{
			hitByMe.add((NPC) e.getActor());
		}
	}

	/** Killing an NPC you hit pays {@link Settings#GP_PER_KILL_LEVEL} gp for each of its combat levels. */
	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		NPC npc = e.getNpc();
		if (!hitByMe.remove(npc) || !npc.isDead())
		{
			return;
		}
		long gp = state.scaled(GoldmanState.Payout.KILLS, LevelBonuses.forKill(npc.getCombatLevel(), Settings.GP_PER_KILL_LEVEL));
		if (gp > 0)
		{
			state.addBalance(gp);
			announce(ChatMessageType.SPAM, gp, "killing " + Text.removeTags(npc.getName() == null ? "an NPC" : npc.getName()));
		}
	}

	/** Writes "+N gp for what" in the chatbox. */
	private void announce(ChatMessageType type, long gp, String what)
	{
		if (gp > 0)
		{
			client.addChatMessage(type, "",
				"<col=ffffff>Goldman Mode:</col> <col=ffff00>+" + QuantityFormatter.formatNumber(gp) + " gp for " + what + ".</col>", null);
		}
	}

	/** combat level from the real levels we are tracking */
	private int combatLevel()
	{
		return Experience.getCombatLevel(
			lastLevel.getOrDefault(Skill.ATTACK, 1), lastLevel.getOrDefault(Skill.STRENGTH, 1),
			lastLevel.getOrDefault(Skill.DEFENCE, 1), lastLevel.getOrDefault(Skill.HITPOINTS, 10),
			lastLevel.getOrDefault(Skill.MAGIC, 1), lastLevel.getOrDefault(Skill.RANGED, 1),
			lastLevel.getOrDefault(Skill.PRAYER, 1));
	}

	@Subscribe
	public void onChatMessage(ChatMessage e)
	{
		achievements.onChatMessage(e.getType(), e.getMessage());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		achievements.onWidgetLoaded(e.getGroupId());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState gs = e.getGameState();
		if (gs == GameState.LOGIN_SCREEN || gs == GameState.LOGGING_IN || gs == GameState.HOPPING || gs == GameState.CONNECTION_LOST)
		{
			xpBaselined = false; // look at everyone's xp again once we are back in the game
			hitByMe.clear();
			achievements.reset();
		}
		if (gs == GameState.LOGIN_SCREEN || gs == GameState.HOPPING)
		{
			mapWindow.setPlayer(null);
			state.setCurrent(null);
			mapWindow.closeLater();
		}
		if (gs == GameState.LOGIN_SCREEN)
		{
			mapWindow.resetView(); // next login starts on the whole map again
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		baselineXp();
		achievements.onGameTick();
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return;
		}
		WorldPoint wp = me.getWorldLocation();
		state.setCurrent(wp == null ? null : state.getIndex().areaAt(wp.getX(), wp.getY()));
		mapWindow.setPlayer(wp == null || Instances.isInstanced(client) ? null : wp);
	}

	@Subscribe
	public void onClientTick(ClientTick t)
	{
		clickBlocker.onClientTick();
		clogTooltip.onClientTick();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded e)
	{
		clickBlocker.onMenuEntryAdded(e);
		mapWindow.onMenuEntryAdded(e);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		mapWindow.onMenuOptionClicked(e);
		clickBlocker.onMenuOptionClicked(e);
	}
}

package com.goldmanmode;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
