/**
 * The map pictures: 256x256 pixel squares at several zoom levels (z = -3, 2048 tiles a side, to z = 4, 16 pixels a
 * tile), fetched when they come into view and cached on disk. Only squares asked for since the last {@link #endFrame()}
 * are fetched, so scrolling past something never queues it.
 */
@Slf4j
final class MapTiles
{
	static final int SIZE = 256;
	static final int MIN_Z = -3;
	static final int MAX_Z = 4;
	static final String URL = "https://mejrs.github.io/layers_osrs/mapsquares/-1/%d/0_%d_%d.png";
	/** says who is asking and where to reach the author, as the map server's owner would want */
	static final String USER_AGENT = "Goldman Mode RuneLite plugin (https://github.com/mootrius/goldman-mode)";
	private static final int MAX_CACHED = 420;
	private static final long RETRY_MS = 20_000;
	private static final int WORKERS = 4;

	static long key(int z, int tx, int ty)
	{
		return ((long) (z + 8) << 44) | ((long) (tx & 0x3FFFFF) << 22) | (ty & 0x3FFFFF);
	}

	/** world tiles covered by one square side */
	static int span(int z)
	{
		return z >= 0 ? SIZE >> z : SIZE << -z;
	}

	/** the zoom level whose pictures are right for this many physical pixels per tile */
	static int levelFor(double pixelsPerTile)
	{
		// a little upscaling (12%) is better than loading the next level up
		int z = (int) Math.ceil(Math.log(pixelsPerTile / 1.12) / Math.log(2) - 1e-9);
		return Math.max(MIN_Z, Math.min(MAX_Z, z));
	}

	private final OkHttpClient http; // null: disk only
	private final Filepath dir;
	private final MapRegions regions;
	private final Runnable onChange;

	private final Map<Long, BufferedImage> cache = new LinkedHashMap<Long, BufferedImage>(512, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, BufferedImage> e)
		{
			return size() > MAX_CACHED;
		}
	};
	private final Object lock = new Object();
	private final ArrayDeque<long[]> queue = new ArrayDeque<>();
	private final Set<Long> loading = new HashSet<>();
	private final Map<Long, Long> failed = new HashMap<>();
	private final Set<Long> absent = java.util.concurrent.ConcurrentHashMap.newKeySet();
	private final LinkedHashSet<long[]> wanted = new LinkedHashSet<>();
	private final Set<Long> wantedKeys = new HashSet<>();
	private volatile boolean running = true;
	private volatile int failures;
	private final ExecutorService executor;
	private int active; // downloads running, guarded by lock

	MapTiles(OkHttpClient http, Filepath dir, MapRegions regions, Runnable onChange, ExecutorService executor)
	{
		this.http = http;
		this.dir = dir;
		this.regions = regions;
		this.onChange = onChange;
		this.executor = executor;
	}

	/** the picture if it is in memory; never loads */
	BufferedImage peek(int z, int tx, int ty)
	{
		synchronized (cache)
		{
			return cache.get(key(z, tx, ty));
		}
	}

	boolean exists(int z, int tx, int ty)
	{
		return regions.hasTile(z, tx, ty) && !absent.contains(key(z, tx, ty));
	}

	/** Tell the loader this square is wanted for the frame being drawn; returns it if already in memory. */
	BufferedImage want(int z, int tx, int ty)
	{
		BufferedImage img = peek(z, tx, ty);
		if (img == null && exists(z, tx, ty))
		{
			synchronized (wanted)
			{
				if (wantedKeys.add(key(z, tx, ty)))
				{
					wanted.add(new long[]{z, tx, ty});
				}
			}
		}
		return img;
	}

	/** The frame is drawn: the squares wanted by it (in the order asked) replace whatever was queued before. */
	void endFrame()
	{
		long now = System.currentTimeMillis();
		synchronized (lock)
		{
			queue.clear();
			synchronized (wanted)
			{
				for (long[] w : wanted)
				{
					long k = key((int) w[0], (int) w[1], (int) w[2]);
					Long f = failed.get(k);
					if (!loading.contains(k) && (f == null || now - f > RETRY_MS))
					{
						queue.add(w);
					}
				}
				wanted.clear();
				wantedKeys.clear();
			}
		}
		pump();
	}

	/** how many squares are being fetched or waiting */
	int busy()
	{
		synchronized (lock)
		{
			return loading.size() + queue.size();
		}
	}

	/** true while recent downloads keep failing */
	boolean offline()
	{
		return failures >= 3;
	}

	void releaseMemory()
	{
		synchronized (cache)
		{
			cache.clear();
		}
	}

	void shutdown()
	{
		running = false; // downloads already started finish by themselves
		synchronized (lock)
		{
			queue.clear();
		}
	}

	/** Starts downloads from the front of the queue until {@link #WORKERS} are running. */
	private void pump()
	{
		synchronized (lock)
		{
			while (running && active < WORKERS && !queue.isEmpty())
			{
				long[] w = queue.pollFirst();
				long k = key((int) w[0], (int) w[1], (int) w[2]);
				if (!loading.add(k))
				{
					continue;
				}
				active++;
				try
				{
					executor.execute(() -> fetch(w, k));
				}
				catch (RejectedExecutionException e)
				{
					loading.remove(k);
					active--;
					return;
				}
			}
		}
	}

	private void fetch(long[] w, long k)
	{
		try
		{
			BufferedImage img = load((int) w[0], (int) w[1], (int) w[2]);
			if (img != null)
			{
				synchronized (cache)
				{
					cache.put(k, img);
				}
				failures = 0;
				onChange.run();
			}
		}
		catch (Exception e)
		{
			log.debug("map tile {} failed: {}", java.util.Arrays.toString(w), e.toString());
			synchronized (lock)
			{
				failed.put(k, System.currentTimeMillis());
			}
			failures++;
		}
		finally
		{
			synchronized (lock)
			{
				loading.remove(k);
				active--;
			}
			pump();
		}
	}

	private Filepath fileOf(int z, int tx, int ty)
	{
		return dir.joinSegment(Integer.toString(z)).joinSegment("0_" + tx + "_" + ty + ".png");
	}

	private BufferedImage load(int z, int tx, int ty) throws IOException
	{
		Filepath f = fileOf(z, tx, ty);
		byte[] data = null;
		if (f.isFile() && f.size() > 0)
		{
			try (InputStream in = f.openInputStream())
			{
				data = in.readAllBytes();
			}
		}
		else if (http != null)
		{
			Request req = new Request.Builder().url(String.format(URL, z, tx, ty)).header("User-Agent", USER_AGENT).build();
			try (Response resp = http.newCall(req).execute())
			{
				if (resp.code() == 404)
				{
					absent.add(key(z, tx, ty));
					return null;
				}
				if (!resp.isSuccessful() || resp.body() == null)
				{
					throw new IOException("HTTP " + resp.code());
				}
				data = resp.body().bytes();
			}
			BufferedImage test = decode(data);
			if (test == null)
			{
				throw new IOException("not a picture");
			}
			f.getParent().createDirectories();
			Filepath tmp = f.getParent().joinSegment(f.getFileName() + "." + java.util.UUID.randomUUID() + ".part");
			tmp.write(data);
			f.deleteIfExists();
			tmp.moveTo(f);
			return test;
		}
		if (data == null)
		{
			return null;
		}
		BufferedImage img = decode(data);
		if (img == null)
		{
			f.deleteIfExists(); // broken file: fetch it again next time
		}
		return img;
	}

	private static BufferedImage decode(byte[] data) throws IOException
	{
		BufferedImage src = ImageIO.read(new ByteArrayInputStream(data));
		if (src == null)
		{
			return null;
		}
		BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_RGB);
		java.awt.Graphics2D g = out.createGraphics();
		g.drawImage(src, 0, 0, null);
		g.dispose();
		return out;
	}
}

package com.goldmanmode;

/**
 * Where the map is looking: the world point (tiles, y north) in the middle of the screen and how many screen pixels
 * one tile is. All the pixel/tile maths in one place.
 */
final class MapViewport
{
	double cx, cy;
	double scale = 4;
	int w = 800, h = 600;

	double sx(double wx)
	{
		return w / 2.0 + (wx - cx) * scale;
	}

	double sy(double wy)
	{
		return h / 2.0 - (wy - cy) * scale;
	}

	double wx(double sx)
	{
		return cx + (sx - w / 2.0) / scale;
	}

	double wy(double sy)
	{
		return cy - (sy - h / 2.0) / scale;
	}

	void panPixels(double dx, double dy)
	{
		cx -= dx / scale;
		cy += dy / scale;
	}

	/** Zoom so that world point (ax, ay) stays under screen point (sx, sy). */
	void zoomKeeping(double ax, double ay, double sx, double sy, double newScale)
	{
		scale = newScale;
		cx = ax - (sx - w / 2.0) / scale;
		cy = ay + (sy - h / 2.0) / scale;
	}

	/** The scale at which the box (world tiles) just fits the screen, with a margin in pixels. */
	double fitScale(double[] box, double margin)
	{
		double sw = Math.max(1, w - 2 * margin), sh = Math.max(1, h - 2 * margin);
		return Math.min(sw / (box[2] - box[0]), sh / (box[3] - box[1]));
	}

	void fit(double[] box, double margin)
	{
		scale = fitScale(box, margin);
		cx = (box[0] + box[2]) / 2;
		cy = (box[1] + box[3]) / 2;
	}

	/** Keep the middle of the screen inside the box (plus a little slack). */
	void clampCentre(double[] box, double slackTiles)
	{
		cx = Math.max(box[0] - slackTiles, Math.min(box[2] + slackTiles, cx));
		cy = Math.max(box[1] - slackTiles, Math.min(box[3] + slackTiles, cy));
	}
}

package com.goldmanmode;

import net.runelite.api.Perspective;

/**
 * Tile -> minimap pixel maths, the same as RuneLite's {@code Perspective.localToMinimap}
 * (minimap zoom in pixels per tile, rotated by the camera yaw), but without its distance cut-off, so whole
 * area outlines can be projected even when some of their corners are far off the minimap.
 */
final class MinimapMath
{
	private MinimapMath()
	{
	}

	/**
	 * @param dxTiles   tiles east of the camera focus (the player)
	 * @param dyTiles   tiles north of the camera focus
	 * @param zoom      client.getMinimapZoom(): minimap pixels per tile (4 by default)
	 * @param yawTarget client.getCameraYawTarget()
	 * @param out       receives the pixel offset from the centre of the minimap: out[0] right, out[1] down
	 */
	static void project(double dxTiles, double dyTiles, double zoom, int yawTarget, double[] out)
	{
		int yaw = yawTarget & 0x3FFF;
		double sin = Perspective.SINE14[yaw] / 65536.0;
		double cos = Perspective.COSINE14[yaw] / 65536.0;
		double xs = dxTiles * zoom;
		double ys = dyTiles * zoom;
		out[0] = cos * xs + sin * ys;
		out[1] = sin * xs - cos * ys;
	}
}

package com.goldmanmode;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/** What every quest, diary task, combat achievement and collection log item pays, from the economy spreadsheet (payouts.json). */
final class Payouts
{
	/** gp for one task and gp for finishing the tier, by tier name (lower case) */
	static final class Tier
	{
		final long task;
		final long bonus;

		Tier(long task, long bonus)
		{
			this.task = task;
			this.bonus = bonus;
		}
	}

	/** a quest title found in some text and what it pays */
	static final class QuestHit
	{
		final String name;
		final long gp;

		QuestHit(String name, long gp)
		{
			this.name = name;
			this.gp = gp;
		}
	}

	private final Map<String, Long> quests = new HashMap<>();
	/** quest names, longest first, so "Dragon Slayer II" is found before "Dragon Slayer I" */
	private final List<String> questNames = new ArrayList<>();
	private final Map<String, Long> clog = new HashMap<>();
	private final Map<String, Tier> diaries = new HashMap<>();
	private final Map<String, Tier> combat = new HashMap<>();

	static Payouts load()
	{
		try (InputStream in = Payouts.class.getResourceAsStream("payouts.json"))
		{
			if (in == null)
			{
				return new Payouts();
			}
			return parse(new InputStreamReader(in, StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			return new Payouts();
		}
	}

	/** quest payouts are paid this many times what the spreadsheet says */
	static final long QUEST_MULTIPLIER = 2;
	/** achievement diary payouts (each task and each tier bonus) are paid this many times what the spreadsheet says */
	static final long DIARY_MULTIPLIER = 2;

	static Payouts parse(Reader r)
	{
		Payouts p = new Payouts();
		JsonObject root = new JsonParser().parse(r).getAsJsonObject();
		for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("quests").entrySet())
		{
			p.quests.put(normalise(e.getKey()), QUEST_MULTIPLIER * e.getValue().getAsLong());
		}
		p.questNames.addAll(p.quests.keySet());
		p.questNames.sort(Comparator.comparingInt(String::length).reversed().thenComparing(Comparator.naturalOrder()));
		for (Map.Entry<String, JsonElement> e : root.getAsJsonObject("clog").entrySet())
		{
			p.clog.put(normalise(e.getKey()), e.getValue().getAsLong());
		}
		readTiers(root.getAsJsonObject("diaries"), p.diaries, DIARY_MULTIPLIER);
		readTiers(root.getAsJsonObject("combat"), p.combat, 1);
		return p;
	}

	private static void readTiers(JsonObject o, Map<String, Tier> into, long multiplier)
	{
		for (Map.Entry<String, JsonElement> e : o.entrySet())
		{
			JsonObject t = e.getValue().getAsJsonObject();
			into.put(e.getKey().toLowerCase(Locale.ROOT), new Tier(multiplier * t.get("task").getAsLong(), multiplier * t.get("bonus").getAsLong()));
		}
	}

	/** lower case, no colour tags, straight apostrophes, single spaces */
	static String normalise(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replaceAll("<[^>]*>", "")
			.replace('’', '\'').replace('‘', '\'')
			.replace(' ', ' ')
			.trim().replaceAll("\\s+", " ")
			.toLowerCase(Locale.ROOT);
	}

	int questCount()
	{
		return quests.size();
	}

	int clogCount()
	{
		return clog.size();
	}

	long questTotal()
	{
		return quests.values().stream().mapToLong(Long::longValue).sum();
	}

	long clogTotal()
	{
		return clog.values().stream().mapToLong(Long::longValue).sum();
	}

	/**
	 * The quest named somewhere in some text such as "You have completed Dragon Slayer II!"
	 * (the longest quest name wins, and a name must stand on its own, not sit inside a longer word).
	 */
	QuestHit questIn(String text)
	{
		String t = normalise(text);
		for (String name : questNames)
		{
			int from = 0;
			int at;
			while ((at = t.indexOf(name, from)) >= 0)
			{
				boolean startOk = at == 0 || !Character.isLetterOrDigit(t.charAt(at - 1));
				int end = at + name.length();
				boolean endOk = end >= t.length() || !Character.isLetterOrDigit(t.charAt(end));
				if (startOk && endOk)
				{
					return new QuestHit(name, quests.get(name));
				}
				from = at + 1;
			}
		}
		return null;
	}

	/** gp a quest pays, by its exact name as listed in the game's quest list, or -1 if it isn't one we know */
	long quest(String name)
	{
		Long v = quests.get(normalise(name));
		return v == null ? -1 : v;
	}

	/** gp for a collection log item (by its name in the game), or -1 if it isn't one we know */
	long clogItem(String name)
	{
		Long v = clog.get(normalise(name));
		return v == null ? -1 : v;
	}

	Tier diary(String tier)
	{
		return diaries.get(tier.toLowerCase(Locale.ROOT));
	}

	Tier combat(String tier)
	{
		return combat.get(tier.toLowerCase(Locale.ROOT));
	}
}

package com.goldmanmode;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.IntConsumer;
import java.util.function.IntPredicate;
import javax.swing.JComponent;

/**
 * A row of equal buttons joined into one bar (a "segmented control"). What each segment looks like is up to the
 * {@link Cell}; which ones count as selected comes from {@code selected}; a click calls {@code onClick}. It draws
 * everything itself (no text glyphs a font might lack) and has no tooltips.
 */
final class SegmentBar extends JComponent
{
	interface Cell
	{
		/** draws the content of one segment inside {@code r} */
		void paint(Graphics2D g, Rectangle r, boolean selected);
	}

	static final Color OFF = new Color(0x1E, 0x1E, 0x1E);
	static final Color ON = new Color(0x55, 0x55, 0x55);
	/** the same two colours while the mouse is over a segment: a touch brighter */
	static final Color OFF_HOVER = new Color(0x2C, 0x2C, 0x2C);
	static final Color ON_HOVER = new Color(0x68, 0x68, 0x68);
	static final Color EDGE = new Color(0x3A, 0x3A, 0x3A);

	private final Cell[] cells;
	private final IntPredicate selected;
	private int hover = -1;

	SegmentBar(Cell[] cells, IntPredicate selected, IntConsumer onClick)
	{
		this.cells = cells;
		this.selected = selected;
		setPreferredSize(new Dimension(10, 28));
		setOpaque(false);
		MouseAdapter mouse = new MouseAdapter()
		{
			private int at(MouseEvent e)
			{
				int i = e.getX() * cells.length / Math.max(1, getWidth());
				return i >= 0 && i < cells.length ? i : -1;
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				int i = at(e);
				if (i >= 0)
				{
					onClick.accept(i);
					repaint();
				}
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				setHover(at(e));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setHover(-1);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	private void setHover(int i)
	{
		if (i != hover)
		{
			hover = i;
			repaint();
		}
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		for (int i = 0; i < cells.length; i++)
		{
			int x0 = i * w / cells.length;
			int x1 = (i + 1) * w / cells.length;
			Rectangle r = new Rectangle(x0, 0, x1 - x0, h);
			boolean on = selected.test(i);
			g.setColor(i == hover ? (on ? ON_HOVER : OFF_HOVER) : (on ? ON : OFF));
			g.fillRect(r.x, r.y, r.width, r.height);
			g.setColor(EDGE);
			g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
			Graphics2D cell = (Graphics2D) g.create(); // each cell gets its own graphics, so its icon's settings don't leak into the next border
			cell.clipRect(r.x, r.y, r.width, r.height);
			cells[i].paint(cell, r, on);
			cell.dispose();
		}
		g.dispose();
	}

	// ------------------------------------------------------------------ icons

	/** a padlock drawn as thin line art (like the search icon): closed (locked) or with its shackle lifted (unlocked) */
	static void lock(Graphics2D g, Rectangle r, boolean closed, Color colour)
	{
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		double cx = r.x + r.width / 2.0;
		double cy = r.y + r.height / 2.0;
		g.setColor(colour);
		g.setStroke(new java.awt.BasicStroke(1.5f, java.awt.BasicStroke.CAP_ROUND, java.awt.BasicStroke.JOIN_ROUND));
		// the body, with a keyhole
		double bx = cx - 5.5;
		double by = cy - 1.5;
		g.draw(new java.awt.geom.RoundRectangle2D.Double(bx, by, 11, 8.5, 2, 2));
		g.fill(new java.awt.geom.Ellipse2D.Double(cx - 1, by + 2.6, 2, 2));
		// the shackle: the same loop either way. Unlocked has the lower part of its right side erased
		g.draw(new java.awt.geom.Line2D.Double(bx + 2, by - 2, bx + 2, by));
		if (closed)
		{
			g.draw(new java.awt.geom.Arc2D.Double(bx + 2, by - 6.5, 7, 9, 0, 180, java.awt.geom.Arc2D.OPEN));
			g.draw(new java.awt.geom.Line2D.Double(bx + 9, by - 2, bx + 9, by));
		}
		else
		{
			g.draw(new java.awt.geom.Arc2D.Double(bx + 2, by - 6.5, 7, 9, 40, 140, java.awt.geom.Arc2D.OPEN));
		}
		g.setStroke(new java.awt.BasicStroke(1f));
	}

	/** a small triangle pointing up or down with its centre at (cx, cy) */
	static void arrow(Graphics2D g, int cx, int cy, boolean up, Color colour)
	{
		int[] xs = {cx - 4, cx + 4, cx};
		int[] ys = up ? new int[]{cy + 3, cy + 3, cy - 3} : new int[]{cy - 3, cy - 3, cy + 3};
		g.setColor(colour);
		g.fillPolygon(xs, ys, 3);
	}
}

package com.goldmanmode;

import java.awt.Color;

/** The fixed look and rules of Goldman Mode (the options you can change are in {@link GoldmanModeConfig}). */
final class Settings
{
	private Settings()
	{
	}

	// the barrier around locked areas in the game world
	static final Color BARRIER_COLOUR = new Color(0x64FF0000, true); // alpha, red, green, blue
	static final int BARRIER_HEIGHT = 250;
	static final int BARRIER_DISTANCE = 15;
	static final int BARRIER_FADE_WIDTH = 5;
	static final int PULSE_STRENGTH = 60;
	static final int PULSE_PERIOD_MS = 1500;

	// the minimap
